/*
 *-----------------------------------------------------------------------------
 *                           Syntax
 *-----------------------------------------------------------------------------
 *
 * Syntax:    "[<password> ]<command>"
 *
 *               - <password>: password
 *               - <command> : command text
 *
 *               (*) Optional
 *
 * Examples:  "STATUS"            (            <command>)
 * Examples:  "123456 STATUS"     ( <password> <command>)
 */

/*
 *-----------------------------------------------------------------------------
 *                           PROGRAM commands
 *-----------------------------------------------------------------------------
 *
 *  *** status reading ***
 *  - "TIME"                  |   "TIME"
 *  - "PHONESTATUS"           |   "PHONESTATUS"
 *  - "PHONEINFO1"            |   "PHONEINFO1"
 *  - "PHONEINFO2"            |   "PHONEINFO2"
 *  - "SIMINFO"               |   "SIMINFO"
 *  - "SIMPININFO"            |   "SIMPININFO"
 *  - "PHONECOUNTERS"         |   "PHONECOUNTERS"
 *  - "ALARMCOUNTERS"         |   "ALARMCOUNTERS"
 *  - "FSINFO"                |   "FSINFO"
 *
 *  *** configuration (set) ***
 *  - "SETAPN"                |   "SETAPN SERV=<apn> USER=<username> PWD=<password>"
 *  - "SETDNS"                |   "SETDNS DNS1=<dns1> DNS2=<dns2>"
 *  - "SETADC0"               |   "SETADC0 CALIBRATION=<calibration> POLY=<a6>,<a5>,<a4>,<a3>,<a2>,<a1>,<a0>"
 *  - "SETADC1"               |   "SETADC1 CALIBRATION=<calibration> POLY=<a6>,<a5>,<a4>,<a3>,<a2>,<a1>,<a0>"
 *  - "SETADC2"               |   "SETADC2 CALIBRATION=<calibration> POLY=<a6>,<a5>,<a4>,<a3>,<a2>,<a1>,<a0>"
 *  - "SETADC3"               |   "SETADC3 CALIBRATION=<calibration> POLY=<a6>,<a5>,<a4>,<a3>,<a2>,<a1>,<a0>"
 *  - "SETPOD"                |   "SETPOD POD=<pod>"
 *  - "SETCMDDETACHMENT"      |   "SETCMDDETACHMENT CMD=<command>"
 *  - "SETCMDRESTORE"         |   "SETCMDRESTORE CMD=<command>"
 *  - "SETCMDSTATUS"          |   "SETCMDSTATUS CMD=<command>"
 *  - "SETCMDRESET"           |   "SETCMDRESET CMD=<command>"
 *  - "SETANSDETACHMENT"      |   "SETANSDETACHMENT ANS=<answer>"
 *  - "SETANSRESTORE"         |   "SETANSRESTORE ANS=<answer>"
 *  - "SETANSSTATUS"          |   "SETANSSTATUS ANS=<answer>"
 *  - "SETANSRESET"           |   "SETANSRESET ANS=<answer>"
 *  - "SETAUTORESTORE"        |   "SETAUTORESTORE ENABLE=<status> WAIT=<wait>"
 *  - "SETAUTORECONNECTION"   |   "SETAUTORECONNECTION ENABLE=<status> DELAY=<delay> TIME=<time>"
 *  - "SETIN3"                |   "SETIN3 "
 *  - "SETIN4"                |   "SETIN4 "
 *  - "SETOUT1"               |   "SETOUT1 ACTIVE=<active_status>"
 *  - "SETOUT2"               |   "SETOUT2 ACTIVE=<active_status>"
 *  - "SETDEVICEID"           |   "SETDEVICEID ID=<device_id>"
 *  - "SETLOG"                |   "SETLOG ENABLE=<status> PERIOD=<period> DURATION=<duration>"
 *  - "SETENERGY"             |   "SETENERGY ENABLE=<status> THRESHOLD=<energy>"
 *  - "SETALARMMODE"          |   "SETALARMMODE MODE=<mode>"
 *  - "SETCMDEXT"             |   "SETCMDEXT CMD=<id_cmd_ext> TEXT=<text_cmd_ext>,<text_cmd>"
 *  - "SETSIMPIN"             |   "SETSIMPIN PIN=<use_pin>"
 *  - "SETANALOGMODE"         |   "SETANALOGMODE MODE=<mode>"
 *  - "SETHOST"               |   "SETHOST HOSTNAME=<host_name> PATHNAME=<path_name> PORT=<port>"
 *  - "SETHOSTTX"             |   "SETHOSTTX HOSTNAME=<host_name> PATHNAME=<path_name> PORT=<port>"
 *  - "SETHOSTDATA"           |   "SETHOSTDATA HOSTNAME=<host_name> PATHNAME=<path_name> PORT=<port>"
 *  - "SETHOSTACCOUNT1"       |   "SETHOSTACCOUNT1 CID=<cid> ID=<id> PW=<pw>"
 *  - "SETHOSTACCOUNT2"       |   "SETHOSTACCOUNT2 KEY=<key>"
 *  - "SETSERIALNUMBER"       |   "SETSERIALNUMBER SN=<serial_number>"
 *
 *  *** configuration (get) ***
 *  - "GETAPN"                |   "GETAPN"
 *  - "GETDNS"                |   "GETDNS"
 *  - "GETADC0"               |   "GETADC0"
 *  - "GETADC1"               |   "GETADC1"
 *  - "GETADC2"               |   "GETADC2"
 *  - "GETADC3"               |   "GETADC3"
 *  - "GETPOD"                |   "GETPOD"
 *  - "GETCMDDETACHMENT"      |   "GETCMDDETACHMENT"
 *  - "GETCMDRESTORE"         |   "GETCMDRESTORE"
 *  - "GETCMDSTATUS"          |   "GETCMDSTATUS"
 *  - "GETCMDRESET"           |   "GETCMDRESET"
 *  - "GETANSDETACHMENT"      |   "GETANSDETACHMENT"
 *  - "GETANSRESTORE"         |   "GETANSRESTORE"
 *  - "GETANSSTATUS"          |   "GETANSSTATUS"
 *  - "GETANSRESET"           |   "GETANSRESET"
 *  - "GETAUTORECONNECTION"   |   "GETAUTORECONNECTION"
 *  - "GETAUTORESTORE"        |   "GETAUTORESTORE"
 *  - "GETIN3"                |   "GETIN3"
 *  - "GETIN4"                |   "GETIN4"
 *  - "GETOUT1"               |   "GETOUT1"
 *  - "GETOUT2"               |   "GETOUT2"
 *  - "GETDEVICEID"           |   "GETDEVICEID"
 *  - "GETLOG"                |   "GETLOG"
 *  - "GETENERGY"             |   "GETENERGY"
 *  - "GETALARMMODE"          |   "GETALARMMODE MODE=<mode>"
 *  - "GETCMDEXT"             |   "GETCMDEXT CMD=<id_cmd_ext>"
 *  - "GETSIMPIN"             |   "GETSIMPIN PIN=<use_pin>"
 *  - "GETANALOGMODE"         |   "GETANALOGMODE MODE=<mode>"
 *  - "GETHOST"               |   "GETHOST HOSTNAME=<host_name> PATHNAME=<path_name> PORT=<port>"
 *  - "GETHOSTTX"             |   "GETHOSTTX HOSTNAME=<host_name> PATHNAME=<path_name> PORT=<port>"
 *  - "GETHOSTDATA"           |   "GETHOSTDATA HOSTNAME=<host_name> PATHNAME=<path_name> PORT=<port>"
 *  - "GETHOSTACCOUNT1"       |   "GETHOSTACCOUNT1 CID=<cid> ID=<id> PW=<pw>"
 *  - "GETHOSTACCOUNT2"       |   "GETHOSTACCOUNT2 KEY=<key>"
 *  - "GETSERIALNUMBER"       |   "GETSERIALNUMBER"
 *
 *  *** telecontrol ***
 *  - "DEFAULT"               |   "DEFAULT DATA=<data_type>"
 *  - "AUTOSYNCHRONIZE"       |   "AUTOSYNCHRONIZE <imei> SYNC=<n_sync> N=<n_sms> *<checksum>"
 *  - "FORMATFS"              |   "FORMATFS"
 *  - "SENDLOG"               |   "SENDLOG"
 *
 *
 * -----------------------------------------------------------------
 *                       DOTA commands
 * -----------------------------------------------------------------
 *  *** telecontrol ***
 *  - "DOTA"                  |   "DOTA M=<mode> P=<port> S=<server> U=<username> P=<password> P=<path> F=<file>"
 */

/*
 *-----------------------------------------------------------------------------
 *                           PROGRAM commands
 *-----------------------------------------------------------------------------
 *  *** status reading ***
 *  - "STATUS"                |   "STATUS"
 *  - "VERSION"               |   "VERSION"
 *  - "GETTIME"               |   "GETTIME"
 *
 *  *** configuration (get) ***
 *  - "SETUP"                 |   "SETUP"
 *
 *  *** configuration (set) ***
 *  - "ADD"                   |   "ADD"
 *  - "REMOVE"                |   "REMOVE"
 *  - "CONTACTS"              |   "CONTACTS"
 *  - "NEWNAME"               |   "NEWNAME"
 *  - "ALARM"                 |   "ALARM"
 *  - "MESSAGE"               |   "MESSAGE"
 *  - "CALIBRATE"             |   "CALIBRATE"
 *  - "SETPSW"                |   "SETPSW"
 *  - "SETREPORT"             |   "SETREPORT"
 *  - "LANGUAGE"              |   "LANGUAGE"
 *  - "LANGUAGE"              |   "LANGUAGE"     // in English for all languages
 *  - "TIMEROUT"              |   "TIMEROUT"
 *  - "FORWARD"               |   "FORWARD"
 *  - "CHRONO"                |   "CHRONO"
 *  - "SUMMER"                |   "SUMMER"
 *  - "WINTER"                |   "WINTER"
 *  - "BUTTONS"               |   "BUTTONS"
 *  - "SMSDELAY"              |   "SMSDELAY"
 *  - "COUNTER"               |   "COUNTER"
 *  - "COUNTERBANDS"          |   "COUNTERBANDS"
 *
 *  *** telecontrol ***
 *  - "TURNON"                |   "TURNON"
 *  - "TURNOFF"               |   "TURNOFF"
 *  - "REGULATE"              |   "REGULATE"
 *  - "ANTIFROST"             |   "ANTIFROST"
 *  - "CREDIT"                |   "CREDIT"
 *  - "DEFAULT"               |   "DEFAULT"
 *  - "SETTIME"               |   "SETTIME"
 *  - "SYNCHRONIZE"           |   "SYNCHRONIZE"
 *  - "RESET"                 |   "RESET"
 *  - "SETCOUNTER"            |   "SETCOUNTER"
 *  - "SETCOUNTERBANDS"       |   "SETCOUNTERBANDS"
 *
 *  *** data acquisition ***
 *  - "COMMANDS"              |   "COMMANDS"
 *
 *
 * -----------------------------------------------------------------
 *                       DOTA commands
 * -----------------------------------------------------------------
 *  *** telecontrol ***
 *  - "DOTA"                  |   "DOTA"
 */


/*
 * SETCMDDETACHMENT CMD="DISTACCO utenza #POD#"
 * SETCMDRESTORE    CMD="RIPRISTINO utenza #POD#"
 * SETCMDSTATUS     CMD="utenza #POD# stato Input - Output"
 * SETCMDRESET      CMD="RESET utenza #POD#"
 *
 * SETANSDETACHMENT ANS="utenza #POD# distaccata - Input=#INPUT1# - Output=#OUTPUT1#"
 * SETANSRESTORE    ANS="utenza #POD# ripristinata - Input=#INPUT1# - Output=#OUTPUT1#"
 * SETANSSTATUS     ANS=“utenza #POD# stato - Input=#INPUT# - Output=#OUTPUT1#"
 * SETANSRESET      ANS=“utenza #POD# RESET #RESETRESULT# - Input=#INPUT1# - Output=#OUTPUT1#"
 */




