/*=============================================================================
 * Function   : ParserRx_ParseCommandGetAnsReset
 *
 * Description: parse the "GETANSRESET" command
 *
 *              ---------------------------------------------------------------
 *              *** Syntax ***
 *
 *              - Command:  "GETANSRESET"
 *
 *              - Answer :  " GETANSRESET - <week_day> <date> <time> - ANS=<answer>"
 *
 *                            - <week_day>: current week day (Mon, Tue, Wed, Thu, Fri, Sat, Sun)
 *                            - <date>    : current date (dd/mm/yyyy)
 *                            - <time>    : current time (hh:mm:ss)
 *
 *                            - <answer>  : answer string (quoted string)
 *              ---------------------------------------------------------------
 *
 *              ---------------------------------------------------------------
 *              *** Example ***
 *
 *              - Command:  "GETANSRESET"
 *
 *              - Answer :  " GETANSRESET - Sat 06/04/2012 12:05:23 - ANS="RESET #POD# EXECUTED""
 *                          " GETANSRESET - Sat 06/04/2012 12:05:23 - ANS=""
 *              ---------------------------------------------------------------
 *
 * Input      : - command_not_to_exe  : indication if the command has to be executed
 *              - ptr_time_tx         : pointer to command transmission time
 *              - ptr_phone_number    : pointer to phone number of the command sender (if it is by SMS)
 *              - is_adm              : indication if the command sender is an administrator
 *              - is_crs              : indication if the command sender is a  Center Service
 *              - is_command_ext      : indication if the command is an extra command
 *              - ptr_command         : pointer to command string to be parsed
 *              - header_error        : header ok status
 *              - ptr_answer_header   : pointer to header answer text
 *              - cmd_accepted        : command accepted indication
 *              - pwd_present         : password present indication
 *              - ptr_report          : pointer where to save the report        indication
 *              - ptr_command_valid   : pointer where to save the command valid indication
 *              - ptr_answer_text     : pointer where to save the answer text
 *              - max_size_answer_text: max size of answer text
 * Output     : - FALSE: parser error
 *              - TRUE : parser OK
 *=============================================================================*/
static bool ParserRx_ParseCommandGetAnsReset(bool command_not_to_exe, CLOCK__TIME *ptr_time_tx, ascii *ptr_phone_number, bool is_adm, bool is_crs, bool is_command_ext, ascii *ptr_command, bool header_error, ascii *ptr_answer_header, bool cmd_accepted, bool pwd_present, bool *ptr_report, bool *ptr_command_valid, u8 *ptr_num_answers, ascii **ptr_answer_text, u8 max_size_answer_text)
{
    /* error flags */
           bool                                  syntax_error;
           bool                                  parameters_error;

    /* password flags */
           bool                                  pwd_incorrect;
           bool                                  pwd_required;

    /* command decoding */
           u8                                    len_command;
           u8                                    len_command_decoded;
           u8                                    len_token;
           ascii                                *ptr_token;

    static COMMANDS__CONFIG__ANSWER_RESET        config_answer_reset;

    static ascii                                 answer_string[106 + 1];

    /* answer to the commmand */
           ascii                                 current_time_string[29 + 1];
           CLOCK__TIME                           current_time;

    /* report flag */
           bool                                  report;

    /* command valid flag */
           bool                                  command_valid;

           bool                                  result;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Command \"GETANSRESET\" received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* set the report flag */
    report           = TRUE;

    /* clear error flags */
    syntax_error     = FALSE;
    parameters_error = FALSE;

    /* clear password flags */
    pwd_incorrect    = FALSE;
    pwd_required     = FALSE;


    /*-----------------------------------------------------------------------------
     * Password verify
     *-----------------------------------------------------------------------------*/
    if (!cmd_accepted)
    {
        if (pwd_present)
            pwd_incorrect = TRUE;
        else
            pwd_required  = TRUE;
    }


    /*-----------------------------------------------------------------------------
     * Command decoding
     *-----------------------------------------------------------------------------*/

    /* check command text length */
    len_command = strlen(ptr_command);

    if (ptr_command[len_command - 1] == ' ')
        syntax_error = TRUE;

    len_command_decoded = 0;

    /* check the header command string */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(ptr_command, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);
            if (len_token != (sizeof(COMMAND__GETANSRESET) - 1))
                syntax_error = TRUE;

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* check the end of string */
    if (!syntax_error)
    {
        if (len_command != len_command_decoded)
            syntax_error = TRUE;
    }

    /* check the parameters values */
    if (!syntax_error)
    {
        // NOTHING TO DO

        parameters_error = FALSE;
    }


    /*-----------------------------------------------------------------------------
     * Command execution
     *-----------------------------------------------------------------------------*/

    /* command execution (only if command decoding is correct: no syntax error and no parameters error) */
    if ((!header_error) && (!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            /* get "answer RESET" configuration */
            Commands_Config_AnswerReset_Get(&config_answer_reset);

            command_valid = TRUE;
        }
    }


    /*-----------------------------------------------------------------------------
     * Answer to the command
     *-----------------------------------------------------------------------------*/

    /* copy the report indication */
    *ptr_report = report;

    /* copy the command valid indication */
    *ptr_command_valid = command_valid;

    /* get the current time */
    result = Clock_GetTime(&current_time);

    /* build the current time string */
    if (result)
    {
        /* current time available */
        sprintf(current_time_string,
                "%.3s %02d/%02d/%04d %02d:%02d:%02d",

                /* weekday */
                Clock_WeekDayString(current_time.week_day), // weekday

                /* date */
                current_time.day,                           // day
                current_time.month,                         // month
                current_time.year,                          // year

                /* time */
                current_time.hour,                          // hour
                current_time.minute,                        // minute
                current_time.second);                       // second
    }
    else
    {
        /* current time not available */
        sprintf(current_time_string,

                /* date */
                "???"
                  " "

                "??"
                  "/"
                "??"
                  "/"
                "????"
                  " "

                /* time */
                "??:??:??");
    }

    /* build the answer string */
    if ((!header_error) && (!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            sprintf(answer_string,
                    "ANS=\"%s\"",
                    config_answer_reset.answer);
        }
    }

    /* build the answer */
    if      (header_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s", COMMAND__GETANSRESET, current_time_string, ptr_answer_header              );
    else if (syntax_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s", COMMAND__GETANSRESET, current_time_string, ANSWER_COMMAND_SYNTAX_ERROR    );
    else if (parameters_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s", COMMAND__GETANSRESET, current_time_string, ANSWER_COMMAND_PARAMETERS_ERROR);
    else if (pwd_required)
        sprintf(ptr_answer_text[0], " %s - %s - %s", COMMAND__GETANSRESET, current_time_string, ANSWER_PASSWORD_REQUIRED       );
    else if (pwd_incorrect)
        sprintf(ptr_answer_text[0], " %s - %s - %s", COMMAND__GETANSRESET, current_time_string, ANSWER_PASSWORD_INCORRECT      );
    else
        sprintf(ptr_answer_text[0], " %s - %s - %s", COMMAND__GETANSRESET, current_time_string, answer_string                  );

    if (strlen(ptr_answer_text[0]) > 160)
        ptr_answer_text[0][160] = 0x00;

    *ptr_num_answers = 1;

    /* print the answer */
    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ptr_answer_text[0], __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    return TRUE;
}




