           u8                         len_command_decoded;
           u8                         len_token;
           ascii                     *ptr_token;

    static ALARM__CONFIG__ALARM_MODE  config_alarm_mode;

           ascii                      mode_char;

    static ascii                      answer_string[6 + 1];

    /* answer to the command */
           ascii                      current_time_string[29 + 1];
           CLOCK__TIME                current_time;

    /* report flag */
           bool                       report;

