/*=============================================================================
 * Function   : ParserRx_ParseCommandDefault
 *
 * Description: parse the "DEFAULT" command
 *
 *              ---------------------------------------------------------------
 *              *** Syntax ***
 *
 *              - Command:  "DEFAULT DATA=<data_type>"
 *
 *                             - <data_type>: data type to be reset to default value (quoted string)
 *                                              "ALL"
 *                                              "NOCONFIGURATIONS"
 *                                              "RESET"
 *                                              "CONFIGURATIONS"
 *                                              "PHONEINFO"
 *                                              "QUEUE"
 *                                              "ALARM"
 *                                              "SYNCHRONIZE"
 *                                              "RANDOMCONFIGURATIONS"
 *                                              "CLOCK"
 *                                              "RETRANSMISSION"
 *                                              "TEMPERATURE_INFO"
 *                                              "INPUT_INFO"
 *                                              "CREDIT_INFO"
 *                                              "OUTPUT_INFO"
 *                                              "LOGS"
 *                                              "F_REGULATION"
 *                                              "DEVICEID"
 *                                              "COUNTERS"
 *
 *              - Answer :  " DEFAULT - <week_day> <date> <time> - <result>"
 *
 *                            - <week_day>: current week day (Mon, Tue, Wed, Thu, Fri, Sat, Sun)
 *                            - <date>    : current date (dd/mm/yyyy)
 *                            - <time>    : current time (hh:mm:ss)
 *
 *                            - <result>  : telecontrol result:
 *                                            "COMMAND EXECUTED"
 *                                            "COMMAND NOT EXECUTED"
 *                                            "COMMAND NOT EXECUTABLE"
 *                                            "COMMAND PARAMETERS ERROR"
 *              ---------------------------------------------------------------
 *
 *              ---------------------------------------------------------------
 *              *** Example ***
 *
 *              - Command:  "DEFAULT"
 *                          "DEFAULT DATA="CONFIGURATION""
 *
 *              - Answer :  " DEFAULT - Sat 06/04/2012 12:05:23 - COMMAND EXECUTED"
 *              ---------------------------------------------------------------
 *
 * Input      : - command_not_to_exe  : indication if the command has to be executed
 *              - ptr_time_tx         : pointer to command transmission time
 *              - ptr_phone_number    : pointer to phone number of the command sender (if it is by SMS)
 *              - is_adm              : indication if the command sender is an administrator
 *              - is_crs              : indication if the command sender is a  Center Service
 *              - is_command_ext      : indication if the command is an extra command
 *              - ptr_command         : pointer to command string to be parsed
 *              - header_error        : header ok status
 *              - ptr_answer_header   : pointer to header answer text
 *              - cmd_accepted        : command accepted indication
 *              - pwd_present         : password present indication
 *              - ptr_report          : pointer where to save the report        indication
 *              - ptr_command_valid   : pointer where to save the command valid indication
 *              - ptr_answer_text     : pointer where to save the answer text
 *              - max_size_answer_text: max size of answer text
 * Output     : - FALSE: parser error
 *              - TRUE : parser OK
 *=============================================================================*/
static bool ParserRx_ParseCommandDefault(bool command_not_to_exe, CLOCK__TIME *ptr_time_tx, ascii *ptr_phone_number, bool is_adm, bool is_crs, bool is_command_ext, ascii *ptr_command, bool header_error, ascii *ptr_answer_header, bool cmd_accepted, bool pwd_present, bool *ptr_report, bool *ptr_command_valid, u8 *ptr_num_answers, ascii **ptr_answer_text, u8 max_size_answer_text)
{
    /* error flags */
           bool        not_executed;
           bool        not_executable;
           bool        syntax_error;
           bool        parameters_error;

    /* password flags */
           bool        pwd_incorrect;
           bool        pwd_required;

    /* command decoding */
           u8          len_command;
           u8          len_command_decoded;
           u8          len_token;
           ascii      *ptr_token;

    static ascii       data_type_string[25 + 1];
           u8          len_data_type_string;

    /* answer to the commmand */
           ascii       current_time_string[29 + 1];
           CLOCK__TIME current_time;

           bool        default_reset;
           bool        default_configurations;
           bool        default_phone_info;
           bool        default_queue;
           bool        default_alarm;
           bool        default_synchronize;
           bool        default_random_configurations;
           bool        default_clock;
           bool        default_retransmission;
           bool        default_temperature_info;
           bool        default_input_info;
           bool        default_credit_info;
           bool        default_output_info;
           bool        default_logs;
           bool        default_f_regulation;
           bool        default_device_id;
           bool        default_counters;
           bool        default_serial_number;

           bool        result;
           bool        result_1;
           bool        result_2;
           s32         result_s32;
           u8          i;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Command \"DEFAULT\" received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* clear error flags */
    not_executed     = FALSE;
    not_executable   = FALSE;
    syntax_error     = FALSE;
    parameters_error = FALSE;

    /* clear password flags */
    pwd_incorrect    = FALSE;
    pwd_required     = FALSE;


    /*-----------------------------------------------------------------------------
     * Password verify
     *-----------------------------------------------------------------------------*/
    if (!cmd_accepted)
    {
        if (pwd_present)
            pwd_incorrect = TRUE;
        else
            pwd_required  = TRUE;
    }


    /*-----------------------------------------------------------------------------
     * Command decoding
     *-----------------------------------------------------------------------------*/

    /* check command text length */
    len_command = strlen(ptr_command);

    if (ptr_command[len_command - 1] == ' ')
        syntax_error = TRUE;

    len_command_decoded = 0;

    /* check the header command string */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(ptr_command, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);
            if (len_token != (sizeof(COMMAND__DEFAULT) - 1))
                syntax_error = TRUE;

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* extract the parameters */

    /* <DATA> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("DATA") - 1), (sizeof("DATA") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "DATA", (sizeof("DATA") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    /* <data_type> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 1, 255, 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(data_type_string, ptr_token + 1, 25);
                data_type_string[len_token - 2] = 0x00;
                len_data_type_string = strlen(data_type_string);
            }
            else
            {
                data_type_string[0] = 0x00;
                len_data_type_string = 0;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }


    /* check the end of string */
    if (!syntax_error)
    {
        if (len_command != len_command_decoded)
            syntax_error = TRUE;
    }

    /* check the parameters values */
    if (!syntax_error)
    {
        if (
             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__ALL                  ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__ALL                  , (sizeof(COMMAND_PAR__DEFAULT__ALL                  ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__NO_CONFIGURATIONS    ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__NO_CONFIGURATIONS    , (sizeof(COMMAND_PAR__DEFAULT__NO_CONFIGURATIONS    ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__RESET                ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__RESET                , (sizeof(COMMAND_PAR__DEFAULT__RESET                ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__CONFIGURATIONS       ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__CONFIGURATIONS       , (sizeof(COMMAND_PAR__DEFAULT__CONFIGURATIONS       ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__PHONE_INFO           ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__PHONE_INFO           , (sizeof(COMMAND_PAR__DEFAULT__PHONE_INFO           ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__QUEUE                ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__QUEUE                , (sizeof(COMMAND_PAR__DEFAULT__QUEUE                ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__ALARM                ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__ALARM                , (sizeof(COMMAND_PAR__DEFAULT__ALARM                ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__SYNCHRONIZE          ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__SYNCHRONIZE          , (sizeof(COMMAND_PAR__DEFAULT__SYNCHRONIZE          ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__RANDOM_CONFIGURATIONS) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__RANDOM_CONFIGURATIONS, (sizeof(COMMAND_PAR__DEFAULT__RANDOM_CONFIGURATIONS) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__CLOCK                ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__CLOCK                , (sizeof(COMMAND_PAR__DEFAULT__CLOCK                ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__RETRANSMISSION       ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__RETRANSMISSION       , (sizeof(COMMAND_PAR__DEFAULT__RETRANSMISSION       ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__TEMPERATURE_INFO     ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__TEMPERATURE_INFO     , (sizeof(COMMAND_PAR__DEFAULT__TEMPERATURE_INFO     ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__INPUT_INFO           ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__INPUT_INFO           , (sizeof(COMMAND_PAR__DEFAULT__INPUT_INFO           ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__CREDIT_INFO          ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__CREDIT_INFO          , (sizeof(COMMAND_PAR__DEFAULT__CREDIT_INFO          ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__OUTPUT_INFO          ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__OUTPUT_INFO          , (sizeof(COMMAND_PAR__DEFAULT__OUTPUT_INFO          ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__LOGS                 ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__LOGS                 , (sizeof(COMMAND_PAR__DEFAULT__LOGS                 ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__F_REGULATION         ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__F_REGULATION         , (sizeof(COMMAND_PAR__DEFAULT__F_REGULATION         ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__DEVICE_ID            ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__DEVICE_ID            , (sizeof(COMMAND_PAR__DEFAULT__DEVICE_ID            ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__COUNTERS             ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__COUNTERS             , (sizeof(COMMAND_PAR__DEFAULT__COUNTERS             ) - 1)) == 0                   ) ))  &&

             (!( (                                                                       (sizeof(COMMAND_PAR__DEFAULT__SERIAL_NUMBER        ) - 1)  == len_data_type_string) &&
                 (strncmp(data_type_string, COMMAND_PAR__DEFAULT__SERIAL_NUMBER        , (sizeof(COMMAND_PAR__DEFAULT__SERIAL_NUMBER        ) - 1)) == 0                   ) ))
           )
        {
            parameters_error = TRUE;
        }
    }


    /*-----------------------------------------------------------------------------
     * Command execution
     *-----------------------------------------------------------------------------*/
    /* command execution (only if command decoding is correct: no syntax error and no parameters error) */
    if ((!header_error) && (!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            default_reset                 = FALSE;
            default_configurations        = FALSE;
            default_phone_info            = FALSE;
            default_queue                 = FALSE;
            default_alarm                 = FALSE;
            default_synchronize           = FALSE;
            default_random_configurations = FALSE;
            default_clock                 = FALSE;
            default_retransmission        = FALSE;
            default_temperature_info      = FALSE;
            default_input_info            = FALSE;
            default_credit_info           = FALSE;
            default_output_info           = FALSE;
            default_logs                  = FALSE;
            default_f_regulation          = FALSE;
            default_device_id             = FALSE;
            default_counters              = FALSE;
            default_serial_number         = FALSE;

            if      (strncmp(data_type_string, COMMAND_PAR__DEFAULT__ALL              , (sizeof(COMMAND_PAR__DEFAULT__ALL                      ) - 1)) == 0)
            {
                default_reset                 = TRUE;
                default_configurations        = TRUE;
                default_phone_info            = TRUE;
                default_queue                 = TRUE;
                default_alarm                 = TRUE;
                default_synchronize           = TRUE;
                default_random_configurations = TRUE;
                default_clock                 = TRUE;
                default_retransmission        = TRUE;
                default_temperature_info      = TRUE;
                default_input_info            = TRUE;
                default_credit_info           = TRUE;
                default_output_info           = TRUE;
                default_logs                  = TRUE;
                default_f_regulation          = TRUE;
                default_device_id             = TRUE;
                default_counters              = TRUE;
                default_serial_number         = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__NO_CONFIGURATIONS, (sizeof(COMMAND_PAR__DEFAULT__NO_CONFIGURATIONS        ) - 1)) == 0)
            {
                default_reset                 = TRUE;
              //default_configurations        = TRUE;
                default_phone_info            = TRUE;
                default_queue                 = TRUE;
                default_alarm                 = TRUE;
                default_synchronize           = TRUE;
                default_random_configurations = TRUE;
                default_clock                 = TRUE;
                default_retransmission        = TRUE;
                default_temperature_info      = TRUE;
                default_input_info            = TRUE;
                default_credit_info           = TRUE;
                default_output_info           = TRUE;
                default_logs                  = TRUE;
                default_f_regulation          = TRUE;
              //default_device_id             = TRUE;
                default_counters              = TRUE;
                default_serial_number         = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__RESET                , (sizeof(COMMAND_PAR__DEFAULT__RESET                ) - 1)) == 0)
            {
                default_reset                 = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__CONFIGURATIONS       , (sizeof(COMMAND_PAR__DEFAULT__CONFIGURATIONS       ) - 1)) == 0)
            {
                default_configurations        = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__PHONE_INFO           , (sizeof(COMMAND_PAR__DEFAULT__PHONE_INFO           ) - 1)) == 0)
            {
                default_phone_info            = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__QUEUE                , (sizeof(COMMAND_PAR__DEFAULT__QUEUE                ) - 1)) == 0)
            {
                default_queue                 = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__ALARM                , (sizeof(COMMAND_PAR__DEFAULT__ALARM                ) - 1)) == 0)
            {
                default_alarm                 = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__SYNCHRONIZE          , (sizeof(COMMAND_PAR__DEFAULT__SYNCHRONIZE          ) - 1)) == 0)
            {
                default_synchronize           = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__RANDOM_CONFIGURATIONS, (sizeof(COMMAND_PAR__DEFAULT__RANDOM_CONFIGURATIONS) - 1)) == 0)
            {
                default_random_configurations = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__CLOCK                , (sizeof(COMMAND_PAR__DEFAULT__CLOCK                ) - 1)) == 0)
            {
                default_clock                 = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__RETRANSMISSION       , (sizeof(COMMAND_PAR__DEFAULT__RETRANSMISSION       ) - 1)) == 0)
            {
                default_retransmission        = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__TEMPERATURE_INFO     , (sizeof(COMMAND_PAR__DEFAULT__TEMPERATURE_INFO     ) - 1)) == 0)
            {
                default_temperature_info      = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__INPUT_INFO           , (sizeof(COMMAND_PAR__DEFAULT__INPUT_INFO           ) - 1)) == 0)
            {
                default_input_info            = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__CREDIT_INFO          , (sizeof(COMMAND_PAR__DEFAULT__CREDIT_INFO          ) - 1)) == 0)
            {
                default_credit_info           = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__OUTPUT_INFO          , (sizeof(COMMAND_PAR__DEFAULT__OUTPUT_INFO          ) - 1)) == 0)
            {
                default_output_info           = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__LOGS                 , (sizeof(COMMAND_PAR__DEFAULT__LOGS                 ) - 1)) == 0)
            {
                default_logs                  = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__F_REGULATION         , (sizeof(COMMAND_PAR__DEFAULT__F_REGULATION         ) - 1)) == 0)
            {
                default_f_regulation          = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__DEVICE_ID            , (sizeof(COMMAND_PAR__DEFAULT__DEVICE_ID            ) - 1)) == 0)
            {
                default_device_id             = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__COUNTERS             , (sizeof(COMMAND_PAR__DEFAULT__COUNTERS             ) - 1)) == 0)
            {
                default_counters              = TRUE;
            }
            else if (strncmp(data_type_string, COMMAND_PAR__DEFAULT__SERIAL_NUMBER        , (sizeof(COMMAND_PAR__DEFAULT__SERIAL_NUMBER        ) - 1)) == 0)
            {
                default_serial_number         = TRUE;
            }

            result_1 = TRUE;
            result_2 = TRUE;

            if (default_reset)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__000_RESET                );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__000_RESET                );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_configurations)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__001_CONFIGURATIONS       );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__001_CONFIGURATIONS       );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_phone_info)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__002_PHONE_INFO           );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__002_PHONE_INFO           );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_queue)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__003_QUEUE                );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__003_QUEUE                );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_alarm)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__004_ALARM                );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__004_ALARM                );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_synchronize)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__005_SYNCHRONIZE          );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__005_SYNCHRONIZE          );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_random_configurations)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__006_RANDOM_CONFIGURATIONS);
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__006_RANDOM_CONFIGURATIONS);

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_clock)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__007_CLOCK                );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__007_CLOCK                );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_retransmission)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__008_RETRANSMISSION       );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__008_RETRANSMISSION       );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_temperature_info)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__009_TEMPERATURE_INFO     );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__009_TEMPERATURE_INFO     );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_input_info)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__010_INPUT_INFO           );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__010_INPUT_INFO           );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_credit_info)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__011_CREDIT_INFO          );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__011_CREDIT_INFO          );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_output_info)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__012_OUTPUT_INFO          );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__012_OUTPUT_INFO          );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_logs)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__013_LOG                  );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__013_LOG                  );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_f_regulation)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__014_F_REGULATION         );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__014_F_REGULATION         );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_device_id)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__015_DEVICE_ID            );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__015_DEVICE_ID            );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_counters)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__016_COUNTERS             );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__016_COUNTERS             );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (default_serial_number)
            {
                if (!command_not_to_exe)
                {
                    result_1 = ProgramFlash_InitFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__017_SERIAL_NUMBER         );
                    result_2 = ProgramFlash_ReadFlashHandle(PROGRAM_FLASH__HANDLE_INDEX__017_SERIAL_NUMBER         );

                    if ((!result_1) || (!result_2))
                       not_executable = TRUE;
                }
            }

            if (!result_1)
                Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "ProgramFlash_InitFlashHandle ERROR", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
            if (!result_2)
                Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "ProgramFlash_ReadFlashHandle ERROR" , __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
        }
    }


    /*-----------------------------------------------------------------------------
     * Answer to the command
     *-----------------------------------------------------------------------------*/

    /* get the current time */
    result = Clock_GetTime(&current_time);

    /* build the current time string */
    if (result)
    {
        /* current time available */
        sprintf(current_time_string,
                "%.3s %02d/%02d/%04d %02d:%02d:%02d",

                /* weekday */
                Clock_WeekDayString(current_time.week_day), // weekday

                /* date */
                current_time.day,                           // day
                current_time.month,                         // month
                current_time.year,                          // year

                /* time */
                current_time.hour,                          // hour
                current_time.minute,                        // minute
                current_time.second);                       // second
    }
    else
    {
        /* current time not available */
        sprintf(current_time_string,

                /* date */
                "???"
                  " "

                "??"
                  "/"
                "??"
                  "/"
                "????"
                  " "

                /* time */
                "??:??:??");
    }

    /* build the answer */
    if      (header_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DEFAULT, current_time_string, ptr_answer_header              , ptr_command);
    else if (syntax_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DEFAULT, current_time_string, ANSWER_COMMAND_SYNTAX_ERROR    , ptr_command);
    else if (parameters_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DEFAULT, current_time_string, ANSWER_COMMAND_PARAMETERS_ERROR, ptr_command);
    else if (pwd_required)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DEFAULT, current_time_string, ANSWER_PASSWORD_REQUIRED       , ptr_command);
    else if (pwd_incorrect)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DEFAULT, current_time_string, ANSWER_PASSWORD_INCORRECT      , ptr_command);
    else if (not_executable)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DEFAULT, current_time_string, ANSWER_COMMAND_NOT_EXECUTABLE  , ptr_command);
    else if (not_executed)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DEFAULT, current_time_string, ANSWER_COMMAND_NOT_EXECUTED    , ptr_command);
    else
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DEFAULT, current_time_string, ANSWER_COMMAND_EXECUTED        , ptr_command);

    if (strlen(ptr_answer_text[0]) > 160)
        ptr_answer_text[0][160] = 0x00;

    *ptr_num_answers = 1;

    /* print the answer */
    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ptr_answer_text[0], __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    return TRUE;
}




/*=============================================================================
 * Function   : ParserRx_ParseCommandAutosynchronize
 *
 * Description: parse the "AUTOSYNCHRONIZE" command
 *
 *              ---------------------------------------------------------------
 *              *** Syntax ***
 *
 *              - Command:  "AUTOSYNCHRONIZE <imei> SYNC=<n_sync> N=<n_sms_m>,<n_sms_t> *<checksum>"
 *
 *                             - <imei>    : phone IMEI
 *                             - <n_sync>  : autosynchronize SMS counter
 *                             - <n_sms_m> : number of SMS transmitted - monthly
 *                             - <n_sms_t> : number of SMS transmitted - total
 *                             - <checksum>: checksum
 *
 *              - Answer :  --- (no answer)
 *              ---------------------------------------------------------------
 *
 *              ---------------------------------------------------------------
 *              *** Example ***
 *
 *              - Command:  "AUTOSYNCHRONIZE 12345678901234 SYNC=12 N=17,89 *38"
 *
 *              - Answer :  --- (no answer)
 *              ---------------------------------------------------------------
 *
 * Input      : - command_not_to_exe  : indication if the command has to be executed
 *              - ptr_time_tx         : pointer to command transmission time
 *              - ptr_phone_number    : pointer to phone number of the command sender (if it is by SMS)
 *              - is_adm              : indication if the command sender is an administrator
 *              - is_crs              : indication if the command sender is a  Center Service
 *              - is_command_ext      : indication if the command is an extra command
 *              - ptr_command         : pointer to command string to be parsed
 *              - header_error        : header ok status
 *              - ptr_answer_header   : pointer to header answer text
 *              - cmd_accepted        : command accepted indication
 *              - pwd_present         : password present indication
 *              - ptr_report          : pointer where to save the report        indication
 *              - ptr_command_valid   : pointer where to save the command valid indication
 *              - ptr_answer_text     : pointer where to save the answer text
 *              - max_size_answer_text: max size of answer text
 * Output     : - FALSE: parser error
 *              - TRUE : parser OK
 *=============================================================================*/
static bool ParserRx_ParseCommandAutosynchronize(bool command_not_to_exe, CLOCK__TIME *ptr_time_tx, ascii *ptr_phone_number, bool is_adm, bool is_crs, bool is_command_ext, ascii *ptr_command, bool header_error, ascii *ptr_answer_header, bool cmd_accepted, bool pwd_present, bool *ptr_report, bool *ptr_command_valid, u8 *ptr_num_answers, ascii **ptr_answer_text, u8 max_size_answer_text)
{
    /* error flags */
           bool                      syntax_error;
           bool                      parameters_error;

    /* password flags */
           bool                      pwd_required;

    /* command decoding */
           u8                        len_command;
           u8                        len_command_decoded;
           u8                        len_token;
           ascii                    *ptr_token;

    /* phone info */
    static PHONE__PHONE_ID           phone_id;

    /* SIM info */
    static PHONE__SIM_ID             sim_id;

    /* phone IMEI received */
    static ascii                     imei_received   [PHONE__LEN_MAX_IMEI    + 1];

    /* SIM IMSI and SIM CCID received */
    static ascii                     imsi_received   [PHONE__LEN_MAX_IMSI    + 1];
    static ascii                     ef_ccid_received[PHONE__LEN_MAX_EF_CCID + 1];

    /* autosynchronize SMS counter */
           SYNCHRONIZE__SMS_COUNTER  sms_counter;

           u16                       n_sync;
           u32                       n_sync_temp;

    /* report flag */
           bool                      report;

    /* command valid flag */
           bool                      command_valid;

           bool                      result;
           s32                       result_s32;
           u8                        i;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Command \"AUTOSYNCHRONIZE\" received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* set the report flag */
    report           = FALSE;

    /* set the command executed flag */
    command_valid    = FALSE;

    /* clear error flags */
    syntax_error     = FALSE;
    parameters_error = FALSE;

    /* clear password flags */
    pwd_required     = FALSE;


    /*-----------------------------------------------------------------------------
     * Password verify
     *-----------------------------------------------------------------------------*/
    if (!cmd_accepted)
    {
        if (!pwd_present)
            pwd_required  = TRUE;
    }


    /*-----------------------------------------------------------------------------
     * Command decoding
     *-----------------------------------------------------------------------------*/

    /* check command text length */
    len_command = strlen(ptr_command);

    if (ptr_command[len_command - 1] == ' ')
        syntax_error = TRUE;

    len_command_decoded = 0;

    /* check the header command string */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(ptr_command, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);
            if (len_token != (sizeof(COMMAND__AUTOSYNCHRONIZE) - 1))
                syntax_error = TRUE;

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }


    /* extract the parameters */

    /* <imei> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("IMEI") - 1), (sizeof("IMEI") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "IMEI", (sizeof("IMEI") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 0, (PHONE__LEN_MAX_IMEI + 2), 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(imei_received, ptr_token + 1, PHONE__LEN_MAX_IMEI);
                imei_received[len_token - 2] = 0x00;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <imsi> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("IMSI") - 1), (sizeof("IMSI") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "IMSI", (sizeof("IMSI") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 0, (PHONE__LEN_MAX_IMSI + 2), 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(imsi_received, ptr_token + 1, PHONE__LEN_MAX_IMSI);
                imsi_received[len_token - 2] = 0x00;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <ef_ccid> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("CCID") - 1), (sizeof("CCID") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "CCID", (sizeof("CCID") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 0, (PHONE__LEN_MAX_EF_CCID + 2), 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(ef_ccid_received, ptr_token + 1, PHONE__LEN_MAX_EF_CCID);
                ef_ccid_received[len_token - 2] = 0x00;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <n_sync> */
    n_sync      = 0;
    n_sync_temp = 0;
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("NSYNC") - 1), (sizeof("NSYNC") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "NSYNC", (sizeof("NSYNC") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__UINT_NUMBER, FALSE, 1, 10, 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
                n_sync_temp = atoi(ptr_token);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* check the end of string */
    if (!syntax_error)
    {
        if (len_command != len_command_decoded)
            syntax_error = TRUE;
    }

    /* check the parameters values */
    if (!syntax_error)
    {
        if (n_sync_temp > 65535)
            parameters_error = TRUE;

        if (!parameters_error)
            n_sync = (u16)n_sync_temp;
    }


    /*-----------------------------------------------------------------------------
     * Command execution
     *-----------------------------------------------------------------------------*/
    /* command execution (only if command decoding is correct: no syntax error and no parameters error) */
    if ((!header_error) && (!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (
             (( cmd_accepted)                  ) ||
             ((!cmd_accepted) && (pwd_required))   // password not required for this command, the command is accepted
           )
        {
            /* print the phone IMEI received */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "IMEI received: \"%s\"", imei_received);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print the SIM IMSI received */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "IMSI received: \"%s\"", imsi_received);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print the SIM CCID received */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "CCID received: \"%s\"", ef_ccid_received);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print the autosynchronize SMS counter */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Autosynchronize SMS counter: %d", n_sync);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


            /* get the phone IDs */
            /* get the SIM   IDs */
            Phone_PhoneId_Get(&phone_id);
            Phone_SimId_Get  (&sim_id  );

            if (
                 (strncmp(imei_received   , phone_id.imei , PHONE__LEN_MAX_IMEI   ) == 0) &&
                 (strncmp(imsi_received   , sim_id.imsi   , PHONE__LEN_MAX_IMSI   ) == 0) &&
                 (strncmp(ef_ccid_received, sim_id.ef_ccid, PHONE__LEN_MAX_EF_CCID) == 0)
               )
            {
                /* signal the autosynchronize SMS reception */
                sms_counter.sms_counter = n_sync;
                Synchronize_Event_SmsRx(sms_counter, ptr_time_tx);

                command_valid = FALSE;    // It is not a command, so it has not to be stored in the received command log
            }
        }
    }


    /*-----------------------------------------------------------------------------
     * Answer to the command
     *-----------------------------------------------------------------------------*/

    /* copy the report indication */
    *ptr_report = report;

    /* copy the command valid indication */
    *ptr_command_valid = command_valid;

    /* build the answer */
    ptr_answer_text[0] = 0x00;   // no answer

    *ptr_num_answers = 0;

    /* print the answer */
    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ptr_answer_text[0], __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    return TRUE;
}




/*=============================================================================
 * Function   : ParserRx_ParseCommandFormatFS
 *
 * Description: parse the "FORMATFS" command
 *
 *              ---------------------------------------------------------------
 *              *** Syntax ***
 *
 *              - Command:  "FORMATFS"
 *
 *              - Answer :  " FORMATFS - <week_day> <date> <time> - <result>"
 *
 *                            - <week_day>: current week day (Mon, Tue, Wed, Thu, Fri, Sat, Sun)
 *                            - <date>    : current date (dd/mm/yyyy)
 *                            - <time>    : current time (hh:mm:ss)
 *
 *                            - <result>  : telecontrol result:
 *                                            "COMMAND EXECUTED"
 *                                            "COMMAND NOT EXECUTED"
 *                                            "COMMAND NOT EXECUTABLE"
 *                                            "COMMAND PARAMETERS ERROR"
 *              ---------------------------------------------------------------
 *
 *              ---------------------------------------------------------------
 *              *** Example ***
 *
 *              - Command:  "FORMATFS"
 *
 *              - Answer :  " FORMATFS - Sat 06/04/2012 12:05:23 - COMMAND EXECUTED"
 *              ---------------------------------------------------------------
 *
 * Input      : - command_not_to_exe  : indication if the command has to be executed
 *              - ptr_time_tx         : pointer to command transmission time
 *              - ptr_phone_number    : pointer to phone number of the command sender (if it is by SMS)
 *              - is_adm              : indication if the command sender is an administrator
 *              - is_crs              : indication if the command sender is a  Center Service
 *              - is_command_ext      : indication if the command is an extra command
 *              - ptr_command         : pointer to command string to be parsed
 *              - header_error        : header ok status
 *              - ptr_answer_header   : pointer to header answer text
 *              - cmd_accepted        : command accepted indication
 *              - pwd_present         : password present indication
 *              - ptr_report          : pointer where to save the report        indication
 *              - ptr_command_valid   : pointer where to save the command valid indication
 *              - ptr_answer_text     : pointer where to save the answer text
 *              - max_size_answer_text: max size of answer text
 * Output     : - FALSE: parser error
 *              - TRUE : parser OK
 *=============================================================================*/
static bool ParserRx_ParseCommandFormatFS(bool command_not_to_exe, CLOCK__TIME *ptr_time_tx, ascii *ptr_phone_number, bool is_adm, bool is_crs, bool is_command_ext, ascii *ptr_command, bool header_error, ascii *ptr_answer_header, bool cmd_accepted, bool pwd_present, bool *ptr_report, bool *ptr_command_valid, u8 *ptr_num_answers, ascii **ptr_answer_text, u8 max_size_answer_text)
{
    /* error flags */
           bool        not_executed;
           bool        not_executable;
           bool        syntax_error;
           bool        parameters_error;

    /* password flags */
           bool        pwd_incorrect;
           bool        pwd_required;

    /* command decoding */
           u8          len_command;
           u8          len_command_decoded;
           u8          len_token;
           ascii      *ptr_token;

    /* answer to the commmand */
           ascii       current_time_string[29 + 1];
           CLOCK__TIME current_time;

           bool        result;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Command \"FORMATFS\" received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* clear error flags */
    not_executed     = FALSE;
    not_executable   = FALSE;
    syntax_error     = FALSE;
    parameters_error = FALSE;

    /* clear password flags */
    pwd_incorrect    = FALSE;
    pwd_required     = FALSE;


    /*-----------------------------------------------------------------------------
     * Password verify
     *-----------------------------------------------------------------------------*/
    if (!cmd_accepted)
    {
        if (pwd_present)
            pwd_incorrect = TRUE;
        else
            pwd_required  = TRUE;
    }


    /*-----------------------------------------------------------------------------
     * Command decoding
     *-----------------------------------------------------------------------------*/

    /* check command text length */
    len_command = strlen(ptr_command);

    if (ptr_command[len_command - 1] == ' ')
        syntax_error = TRUE;

    len_command_decoded = 0;

    /* check the header command string */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(ptr_command, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);
            if (len_token != (sizeof(COMMAND__FORMATFS) - 1))
                syntax_error = TRUE;

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* extract the parameters */
    // NO PARAMETERS

    /* check the end of string */
    if (!syntax_error)
    {
        if (len_command != len_command_decoded)
            syntax_error = TRUE;
    }

    /* check the parameters values */
    if (!syntax_error)
    {
        // NOTHING TO DO

        parameters_error = FALSE;
    }


    /*-----------------------------------------------------------------------------
     * Command execution
     *-----------------------------------------------------------------------------*/
    /* command execution (only if command decoding is correct: no syntax error and no parameters error) */
    if ((!header_error) && (!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            /* format the file system */
            result = FileSystem_Format();
            if (!result)
                not_executable = TRUE;
        }
    }


    /*-----------------------------------------------------------------------------
     * Answer to the command
     *-----------------------------------------------------------------------------*/

    /* get the current time */
    result = Clock_GetTime(&current_time);

    /* build the current time string */
    if (result)
    {
        /* current time available */
        sprintf(current_time_string,
                "%.3s %02d/%02d/%04d %02d:%02d:%02d",

                /* weekday */
                Clock_WeekDayString(current_time.week_day), // weekday

                /* date */
                current_time.day,                           // day
                current_time.month,                         // month
                current_time.year,                          // year

                /* time */
                current_time.hour,                          // hour
                current_time.minute,                        // minute
                current_time.second);                       // second
    }
    else
    {
        /* current time not available */
        sprintf(current_time_string,

                /* date */
                "???"
                  " "

                "??"
                  "/"
                "??"
                  "/"
                "????"
                  " "

                /* time */
                "??:??:??");
    }

    /* build the answer */
    if      (header_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__FORMATFS, current_time_string, ptr_answer_header              , ptr_command);
    else if (syntax_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__FORMATFS, current_time_string, ANSWER_COMMAND_SYNTAX_ERROR    , ptr_command);
    else if (parameters_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__FORMATFS, current_time_string, ANSWER_COMMAND_PARAMETERS_ERROR, ptr_command);
    else if (pwd_required)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__FORMATFS, current_time_string, ANSWER_PASSWORD_REQUIRED       , ptr_command);
    else if (pwd_incorrect)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__FORMATFS, current_time_string, ANSWER_PASSWORD_INCORRECT      , ptr_command);
    else if (not_executable)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__FORMATFS, current_time_string, ANSWER_COMMAND_NOT_EXECUTABLE  , ptr_command);
    else if (not_executed)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__FORMATFS, current_time_string, ANSWER_COMMAND_NOT_EXECUTED    , ptr_command);
    else
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__FORMATFS, current_time_string, ANSWER_COMMAND_EXECUTED        , ptr_command);

    if (strlen(ptr_answer_text[0]) > 160)
        ptr_answer_text[0][160] = 0x00;

    *ptr_num_answers = 1;

    /* print the answer */
    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ptr_answer_text[0], __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    return TRUE;
}




/*=============================================================================
 * Function   : ParserRx_ParseCommandSendLog
 *
 * Description: parse the "SENDLOG" command
 *
 *              ---------------------------------------------------------------
 *              *** Syntax ***
 *
 *              - Command:  "SENDLOG"
 *
 *              - Answer :  " SENDLOG - <week_day> <date> <time> - <result>"
 *
 *                            - <week_day>: current week day (Mon, Tue, Wed, Thu, Fri, Sat, Sun)
 *                            - <date>    : current date (dd/mm/yyyy)
 *                            - <time>    : current time (hh:mm:ss)
 *
 *                            - <result>  : telecontrol result:
 *                                            "COMMAND EXECUTED"
 *                                            "COMMAND NOT EXECUTED"
 *                                            "COMMAND NOT EXECUTABLE"
 *                                            "COMMAND PARAMETERS ERROR"
 *              ---------------------------------------------------------------
 *
 *              ---------------------------------------------------------------
 *              *** Example ***
 *
 *              - Command:  "SENDLOG"
 *
 *              - Answer :  " SENDLOG - Sat 06/04/2012 12:05:23 - COMMAND EXECUTED"
 *              ---------------------------------------------------------------
 *
 * Input      : - command_not_to_exe  : indication if the command has to be executed
 *              - ptr_time_tx         : pointer to command transmission time
 *              - ptr_phone_number    : pointer to phone number of the command sender (if it is by SMS)
 *              - is_adm              : indication if the command sender is an administrator
 *              - is_crs              : indication if the command sender is a  Center Service
 *              - is_command_ext      : indication if the command is an extra command
 *              - ptr_command         : pointer to command string to be parsed
 *              - header_error        : header ok status
 *              - ptr_answer_header   : pointer to header answer text
 *              - cmd_accepted        : command accepted indication
 *              - pwd_present         : password present indication
 *              - ptr_report          : pointer where to save the report        indication
 *              - ptr_command_valid   : pointer where to save the command valid indication
 *              - ptr_answer_text     : pointer where to save the answer text
 *              - max_size_answer_text: max size of answer text
 * Output     : - FALSE: parser error
 *              - TRUE : parser OK
 *=============================================================================*/
static bool ParserRx_ParseCommandSendLog(bool command_not_to_exe, CLOCK__TIME *ptr_time_tx, ascii *ptr_phone_number, bool is_adm, bool is_crs, bool is_command_ext, ascii *ptr_command, bool header_error, ascii *ptr_answer_header, bool cmd_accepted, bool pwd_present, bool *ptr_report, bool *ptr_command_valid, u8 *ptr_num_answers, ascii **ptr_answer_text, u8 max_size_answer_text)
{
    /* error flags */
           bool        not_executed;
           bool        not_executable;
           bool        syntax_error;
           bool        parameters_error;

    /* password flags */
           bool        pwd_incorrect;
           bool        pwd_required;

    /* command decoding */
           u8          len_command;
           u8          len_command_decoded;
           u8          len_token;
           ascii      *ptr_token;

    /* answer to the commmand */
           ascii       current_time_string[29 + 1];
           CLOCK__TIME current_time;

           bool        result;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Command \"SENDLOG\" received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* clear error flags */
    not_executed     = FALSE;
    not_executable   = FALSE;
    syntax_error     = FALSE;
    parameters_error = FALSE;

    /* clear password flags */
    pwd_incorrect    = FALSE;
    pwd_required     = FALSE;


    /*-----------------------------------------------------------------------------
     * Password verify
     *-----------------------------------------------------------------------------*/
    if (!cmd_accepted)
    {
        if (pwd_present)
            pwd_incorrect = TRUE;
        else
            pwd_required  = TRUE;
    }


    /*-----------------------------------------------------------------------------
     * Command decoding
     *-----------------------------------------------------------------------------*/

    /* check command text length */
    len_command = strlen(ptr_command);

    if (ptr_command[len_command - 1] == ' ')
        syntax_error = TRUE;

    len_command_decoded = 0;

    /* check the header command string */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(ptr_command, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);
            if (len_token != (sizeof(COMMAND__SENDLOG) - 1))
                syntax_error = TRUE;

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* extract the parameters */
    // NO PARAMETERS

    /* check the end of string */
    if (!syntax_error)
    {
        if (len_command != len_command_decoded)
            syntax_error = TRUE;
    }

    /* check the parameters values */
    if (!syntax_error)
    {
        // NOTHING TO DO

        parameters_error = FALSE;
    }


    /*-----------------------------------------------------------------------------
     * Command execution
     *-----------------------------------------------------------------------------*/
    /* command execution (only if command decoding is correct: no syntax error and no parameters error) */
    if ((!header_error) && (!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            /* force the current data log file for transmission */
            LogStatus_Event_ForceTransmission();

            /* force a data log transmission */
            TransmissionGprs_Event_DataTxForce();
        }
    }


    /*-----------------------------------------------------------------------------
     * Answer to the command
     *-----------------------------------------------------------------------------*/

    /* get the current time */
    result = Clock_GetTime(&current_time);

    /* build the current time string */
    if (result)
    {
        /* current time available */
        sprintf(current_time_string,
                "%.3s %02d/%02d/%04d %02d:%02d:%02d",

                /* weekday */
                Clock_WeekDayString(current_time.week_day), // weekday

                /* date */
                current_time.day,                           // day
                current_time.month,                         // month
                current_time.year,                          // year

                /* time */
                current_time.hour,                          // hour
                current_time.minute,                        // minute
                current_time.second);                       // second
    }
    else
    {
        /* current time not available */
        sprintf(current_time_string,

                /* date */
                "???"
                  " "

                "??"
                  "/"
                "??"
                  "/"
                "????"
                  " "

                /* time */
                "??:??:??");
    }

    /* build the answer */
    if      (header_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__SENDLOG, current_time_string, ptr_answer_header              , ptr_command);
    else if (syntax_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__SENDLOG, current_time_string, ANSWER_COMMAND_SYNTAX_ERROR    , ptr_command);
    else if (parameters_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__SENDLOG, current_time_string, ANSWER_COMMAND_PARAMETERS_ERROR, ptr_command);
    else if (pwd_required)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__SENDLOG, current_time_string, ANSWER_PASSWORD_REQUIRED       , ptr_command);
    else if (pwd_incorrect)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__SENDLOG, current_time_string, ANSWER_PASSWORD_INCORRECT      , ptr_command);
    else if (not_executable)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__SENDLOG, current_time_string, ANSWER_COMMAND_NOT_EXECUTABLE  , ptr_command);
    else if (not_executed)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__SENDLOG, current_time_string, ANSWER_COMMAND_NOT_EXECUTED    , ptr_command);
    else
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__SENDLOG, current_time_string, ANSWER_COMMAND_EXECUTED        , ptr_command);

    if (strlen(ptr_answer_text[0]) > 160)
        ptr_answer_text[0][160] = 0x00;

    *ptr_num_answers = 1;

    /* print the answer */
    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ptr_answer_text[0], __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    return TRUE;
}




/*=============================================================================
 * Function   : ParserRx_ParseCommandDota
 *
 * Description: parse the "DOTA" command
 *
 *              ---------------------------------------------------------------
 *              *** Syntax ***
 *
 *              - Command:  "DOTA M=<mode> P=<port> S=<server> U=<username> P=<password> P=<path> F=<file>"
 *
 *                            - <mode>    : FTP mode (0: passive mode, 1: active mode)
 *                            - <port>    : FTP port (1-65535)
 *                            - <server>  : FTP server           (quoted string)
 *                            - <username>: FTP server user name (quoted string)
 *                            - <password>: FTP server password  (quoted string)
 *                            - <path>    : path file            (quoted string)
 *                            - <file>    : name file            (quoted string)
 *
 *              - Answer :  " DOTA - <week_day> <date> <time> - <result>"
 *
 *                            - <week_day>: current week day (Mon, Tue, Wed, Thu, Fri, Sat, Sun)
 *                            - <date>    : current date (dd/mm/yyyy)
 *                            - <time>    : current time (hh:mm:ss)
 *
 *                            - <result>  : telecontrol result:
 *                                            "COMMAND EXECUTED"
 *                                            "COMMAND NOT EXECUTED"
 *                                            "COMMAND NOT EXECUTABLE"
 *                                            "COMMAND PARAMETERS ERROR"
 *              ---------------------------------------------------------------
 *
 *              ---------------------------------------------------------------
 *              *** Example ***
 *
 *              - Command:  "DOTA M=0 P=21 S="www.server.it" U="username" PWD="hud6e8ejsas" P="/Download/" F="IREAD.dwl""
 *
 *              - Answer :  " DOTA - Sat 06/04/2012 12:05:23 - COMMAND EXECUTED"
 *              ---------------------------------------------------------------
 *
 * Input      : - command_not_to_exe  : indication if the command has to be executed
 *              - ptr_time_tx         : pointer to command transmission time
 *              - ptr_phone_number    : pointer to phone number of the command sender (if it is by SMS)
 *              - is_adm              : indication if the command sender is an administrator
 *              - is_crs              : indication if the command sender is a  Center Service
 *              - is_command_ext      : indication if the command is an extra command
 *              - ptr_command         : pointer to command string to be parsed
 *              - header_error        : header ok status
 *              - ptr_answer_header   : pointer to header answer text
 *              - cmd_accepted        : command accepted indication
 *              - pwd_present         : password present indication
 *              - ptr_report          : pointer where to save the report        indication
 *              - ptr_command_valid   : pointer where to save the command valid indication
 *              - ptr_answer_text     : pointer where to save the answer text
 *              - max_size_answer_text: max size of answer text
 * Output     : - FALSE: parser error
 *              - TRUE : parser OK
 *=============================================================================*/
static bool ParserRx_ParseCommandDota(bool command_not_to_exe, CLOCK__TIME *ptr_time_tx, ascii *ptr_phone_number, bool is_adm, bool is_crs, bool is_command_ext, ascii *ptr_command, bool header_error, ascii *ptr_answer_header, bool cmd_accepted, bool pwd_present, bool *ptr_report, bool *ptr_command_valid, u8 *ptr_num_answers, ascii **ptr_answer_text, u8 max_size_answer_text)
{
    /* error flags */
           bool                               not_executed;
           bool                               not_executable;
           bool                               syntax_error;
           bool                               parameters_error;

    /* password flags */
           bool                               pwd_incorrect;
           bool                               pwd_required;

    /* command decoding */
           u8                                 len_command;
           u8                                 len_command_decoded;
           u8                                 len_token;
           ascii                             *ptr_token;

    static DOTA_GPRS__GPRS_APN_PARAMETERS     dota_config_gprs_apn_parameters;
    static DOTA_GPRS__GPRS_DNS_PARAMETERS     dota_config_gprs_dns_parameters;
    static DOTA_FTP__FTP_PARAMETERS           dota_config_ftp_parameters;
    static DOTA_MAIN__DOTA_PHONE_NUMBER       dota_phone_number;

    static PHONE__CONFIG__GPRS_APN_PARAMETERS config_gprs_apn_parameters;
    static PHONE__CONFIG__GPRS_DNS_PARAMETERS config_gprs_dns_parameters;

    static u8                                 ftp_mode;
    static u16                                ftp_port;
           u32                                ftp_mode_temp;
           u32                                ftp_port_temp;

    static ascii                              ftp_server   [DOTA_FTP__MAX_LENGTH_FTP_SERVER    + 1];
    static ascii                              ftp_user_name[DOTA_FTP__MAX_LENGTH_FTP_USER_NAME + 1];
    static ascii                              ftp_password [DOTA_FTP__MAX_LENGTH_FTP_PASSWORD  + 1];
    static ascii                              ftp_file_path[DOTA_FTP__MAX_LENGTH_FTP_FILE_PATH + 1];
    static ascii                              ftp_file_name[DOTA_FTP__MAX_LENGTH_FTP_FILE_NAME + 1];

    /* answer to the commmand */
           ascii                              current_time_string[29 + 1];
           CLOCK__TIME                        current_time;

    /* report flag */
           bool                               report;

    /* command valid flag */
           bool                               command_valid;

           bool                               result;
           bool                               result_1;
           bool                               result_2;
           bool                               result_3;
           s32                                result_s32;
           QlOSStatus                         err;
           u8                                 i;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Command \"DOTA\" received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* set the report flag */
    report           = FALSE;

    /* set the command executed flag */
    command_valid    = FALSE;

    /* clear error flags */
    not_executed     = FALSE;
    not_executable   = FALSE;
    syntax_error     = FALSE;
    parameters_error = FALSE;

    /* clear password flags */
    pwd_incorrect    = FALSE;
    pwd_required     = FALSE;


    /*-----------------------------------------------------------------------------
     * Password verify
     *-----------------------------------------------------------------------------*/
    if (!cmd_accepted)
    {
        if (pwd_present)
            pwd_incorrect = TRUE;
        else
            pwd_required  = TRUE;
    }


    /*-----------------------------------------------------------------------------
     * Command decoding
     *-----------------------------------------------------------------------------*/

    /* check command text length */
    len_command = strlen(ptr_command);

    if (ptr_command[len_command - 1] == ' ')
        syntax_error = TRUE;

    len_command_decoded = 0;

    /* check the header command string */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(ptr_command, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);
            if (len_token != (sizeof(COMMAND__DOTA) - 1))
                syntax_error = TRUE;

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* extract the parameters */

    /* <mode> */
    ftp_mode_temp = 0;
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("M") - 1), (sizeof("M") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "M", (sizeof("M") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__UINT_NUMBER, FALSE, 1, 8, 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
                ftp_mode_temp = atoi(ptr_token);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <port> */
    ftp_port_temp = 0;
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("P") - 1), (sizeof("P") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "P", (sizeof("P") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__UINT_NUMBER, FALSE, 1, 8, 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
                ftp_port_temp = atoi(ptr_token);

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <server> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("S") - 1), (sizeof("S") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "S", (sizeof("S") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 0, (DOTA_FTP__MAX_LENGTH_FTP_SERVER + 2), 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(ftp_server, ptr_token + 1, DOTA_FTP__MAX_LENGTH_FTP_SERVER);
                ftp_server[len_token - 2] = 0x00;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <username> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("U") - 1), (sizeof("U") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "U", (sizeof("U") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 0, (DOTA_FTP__MAX_LENGTH_FTP_USER_NAME + 2), 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(ftp_user_name, ptr_token + 1, DOTA_FTP__MAX_LENGTH_FTP_USER_NAME);
                ftp_user_name[len_token - 2] = 0x00;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <password> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("P") - 1), (sizeof("P") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "P", (sizeof("P") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 0, (DOTA_FTP__MAX_LENGTH_FTP_PASSWORD + 2), 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(ftp_password, ptr_token + 1, DOTA_FTP__MAX_LENGTH_FTP_PASSWORD);
                ftp_password[len_token - 2] = 0x00;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <path> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("P") - 1), (sizeof("P") - 1), 0);
            if (!result)
                syntax_error = TRUE;

            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "P", (sizeof("P") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 0, (DOTA_FTP__MAX_LENGTH_FTP_SERVER + 2), 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(ftp_file_path, ptr_token + 1, DOTA_FTP__MAX_LENGTH_FTP_FILE_PATH);
                ftp_file_path[len_token - 2] = 0x00;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* <file> */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, '=');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, FALSE, (sizeof("F") - 1), (sizeof("F") - 1), 0);
            if (!result)
                syntax_error = TRUE;
            /* conversion to capital letters */
            for (i = 0; i < len_token; i++)
                ptr_token[i] = toupper((unsigned char)ptr_token[i]);

            result_s32 = strncmp(ptr_token, "F", (sizeof("F") - 1));
            if (result_s32 != 0)
                syntax_error = TRUE;

            if (len_command != len_command_decoded)
                ptr_token[len_token] = '=';
        }
        else
        {
            syntax_error = TRUE;
        }
    }
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok(NULL, ' ');
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            len_token = (u8)strlen(ptr_token);

            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            result = Utility_CheckString(ptr_token, UTILITY__STRING__TEXT, TRUE, 0, (DOTA_FTP__MAX_LENGTH_FTP_FILE_NAME + 2), 0);
            if (!result)
                syntax_error = TRUE;

            if (result)
            {
                /* copy the token string removing the 2 quote characters */
                strncpy(ftp_file_name, ptr_token + 1, DOTA_FTP__MAX_LENGTH_FTP_FILE_NAME);
                ftp_file_name[len_token - 2] = 0x00;
            }

            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* check the end of string */
    if (!syntax_error)
    {
        if (len_command != len_command_decoded)
            syntax_error = TRUE;
    }

    /* check the parameters values */
    if (!syntax_error)
    {
        if ((ftp_mode_temp != 0) && (ftp_mode_temp != 1))
            parameters_error = TRUE;

        if (ftp_port_temp > 65535)
            parameters_error = TRUE;

        if (!parameters_error)
        {
            ftp_mode = (u8 )ftp_mode_temp;
            ftp_port = (u16)ftp_port_temp;
        }
    }


    /*-----------------------------------------------------------------------------
     * Command execution
     *-----------------------------------------------------------------------------*/

    /* command execution (only if command decoding is correct: no syntax error and no parameters error) */
    if ((!header_error) && (!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            /* print FTP mode */
            if (ftp_mode == DOTA_FTP__FTP_MODE_PASSIVE)
                Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "DOTA FTP mode     : PASSIVE", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
            else
                Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "DOTA FTP mode     : ACTIVE" , __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print FTP port */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "DOTA FTP port     : %d"    , ftp_port     );
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print the FTP server name */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "DOTA FTP Server   : \"%s\"", ftp_server   );
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print the FTP user name */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "DOTA FTP User Name: \"%s\"", ftp_user_name);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print the FTP password */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "DOTA FTP Password : \"%s\"", ftp_password );
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print the File path */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "DOTA FTP File Path: \"%s\"", ftp_file_path);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            /* print the File name */
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "DOTA FTP File Name: \"%s\"", ftp_file_name);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


            /* GPRS APN */
            Phone_Config_ApnParameters_Get(&config_gprs_apn_parameters);                                                                         /* get the GPRS APN */
            strncpy(dota_config_gprs_apn_parameters.apn_server   , config_gprs_apn_parameters.apn_server   , DOTA_GPRS__MAX_LENGTH_GPRS_APN_SERVER   );
            strncpy(dota_config_gprs_apn_parameters.apn_user_name, config_gprs_apn_parameters.apn_user_name, DOTA_GPRS__MAX_LENGTH_GPRS_APN_USER_NAME);
            strncpy(dota_config_gprs_apn_parameters.apn_password , config_gprs_apn_parameters.apn_password , DOTA_GPRS__MAX_LENGTH_GPRS_APN_PASSWORD );
            dota_config_gprs_apn_parameters.apn_server   [DOTA_GPRS__MAX_LENGTH_GPRS_APN_SERVER   ] = 0x00;
            dota_config_gprs_apn_parameters.apn_user_name[DOTA_GPRS__MAX_LENGTH_GPRS_APN_USER_NAME] = 0x00;
            dota_config_gprs_apn_parameters.apn_password [DOTA_GPRS__MAX_LENGTH_GPRS_APN_PASSWORD ] = 0x00;
            result_1 = DotaGprs_Config_ApnParameters_IsValid(&dota_config_gprs_apn_parameters);

            /* GPRS DNS */
            Phone_Config_DnsParameters_Get(&config_gprs_dns_parameters);                                                                         /* get the GPRS DNS */
            strncpy(dota_config_gprs_dns_parameters.dns_1, config_gprs_dns_parameters.dns_1, DOTA_GPRS__MAX_LENGTH_GPRS_DNS_1);
            strncpy(dota_config_gprs_dns_parameters.dns_2, config_gprs_dns_parameters.dns_2, DOTA_GPRS__MAX_LENGTH_GPRS_DNS_2);
            dota_config_gprs_dns_parameters.dns_1[DOTA_GPRS__MAX_LENGTH_GPRS_DNS_1] = 0x00;
            dota_config_gprs_dns_parameters.dns_2[DOTA_GPRS__MAX_LENGTH_GPRS_DNS_2] = 0x00;
            result_2 = DotaGprs_Config_DnsParameters_IsValid(&dota_config_gprs_dns_parameters);

            /* FTP */
            dota_config_ftp_parameters.ftp_mode = ftp_mode;
            dota_config_ftp_parameters.ftp_port = ftp_port;
            strncpy(dota_config_ftp_parameters.ftp_server   , ftp_server   , DOTA_FTP__MAX_LENGTH_FTP_SERVER   );
            strncpy(dota_config_ftp_parameters.ftp_user_name, ftp_user_name, DOTA_FTP__MAX_LENGTH_FTP_USER_NAME);
            strncpy(dota_config_ftp_parameters.ftp_password , ftp_password , DOTA_FTP__MAX_LENGTH_FTP_PASSWORD );
            strncpy(dota_config_ftp_parameters.ftp_file_path, ftp_file_path, DOTA_FTP__MAX_LENGTH_FTP_FILE_PATH);
            strncpy(dota_config_ftp_parameters.ftp_file_name, ftp_file_name, DOTA_FTP__MAX_LENGTH_FTP_FILE_NAME);
            dota_config_ftp_parameters.ftp_server   [DOTA_FTP__MAX_LENGTH_FTP_SERVER   ] = 0x00;
            dota_config_ftp_parameters.ftp_user_name[DOTA_FTP__MAX_LENGTH_FTP_USER_NAME] = 0x00;
            dota_config_ftp_parameters.ftp_password [DOTA_FTP__MAX_LENGTH_FTP_PASSWORD ] = 0x00;
            dota_config_ftp_parameters.ftp_file_path[DOTA_FTP__MAX_LENGTH_FTP_FILE_PATH] = 0x00;
            dota_config_ftp_parameters.ftp_file_name[DOTA_FTP__MAX_LENGTH_FTP_FILE_NAME] = 0x00;
            result_3 = DotaFtp_Config_FtpParameters_IsValid (&dota_config_ftp_parameters);

            if ((!result_1) || (!result_2) || (!result_3))
                not_executable = TRUE;

            if (result_1 && result_2 && result_3)
            {
                if (!command_not_to_exe)
                {
                    /* GPRS APN */
                    DotaGprs_Config_ApnParameters_Set(&dota_config_gprs_apn_parameters);                                                             /* configure the "APN GPRS" configuration for DOTA */
                    DotaFlash_RequestWriteBackup(DOTA_FLASH__HANDLE_INDEX__000_DOTA, DOTA_FLASH__FLASH_ID__000_DOTA__PHASE_1_GPRS_APN_PARAMETERS);   /* request the backup to flash objects */

                    /* GPRS DNS */
                    DotaGprs_Config_DnsParameters_Set(&dota_config_gprs_dns_parameters);                                                             /* configure the "DNS GPRS" configuration for DOTA */
                    DotaFlash_RequestWriteBackup(DOTA_FLASH__HANDLE_INDEX__000_DOTA, DOTA_FLASH__FLASH_ID__000_DOTA__PHASE_1_GPRS_DNS_PARAMETERS);   /* request the backup to flash objects */

                    /* FTP */
                    DotaFtp_Config_FtpParameters_Set (&dota_config_ftp_parameters     );                                                             /* configure the "FTP" configuration for DOTA */
                    DotaFlash_RequestWriteBackup(DOTA_FLASH__HANDLE_INDEX__000_DOTA, DOTA_FLASH__FLASH_ID__000_DOTA__PHASE_1_FTP_PARAMETERS     );   /* request the backup to flash objects */

                    /* phone number of SMS sender */
                    strncpy(dota_phone_number.dota_phone_number, ptr_phone_number, DOTA_MAIN__MAX_LENGTH_PHONE_NUMBER);
                    dota_phone_number.dota_phone_number[DOTA_MAIN__MAX_LENGTH_PHONE_NUMBER] = 0x00;
                    DotaMain_DotaPhoneNumber_Set(&dota_phone_number);                                                                                    /* configure the DOTA phone number for DOTA */
                    DotaFlash_RequestWriteBackup(DOTA_FLASH__HANDLE_INDEX__000_DOTA, DOTA_FLASH__FLASH_ID__000_DOTA__DOTA_PHONE_NUMBER              );   /* request the backup to flash objects */

                    /* creation of timer "TimerDelayDota" */
                    if (!ParserRx_TimerHandler_TimerDelayDota)
                    {
                        err = ql_rtos_timer_create(&ParserRx_TimerHandler_TimerDelayDota, Boot_TaskRef_Main, ParserRx_AdlCallback_Timer_TimerDelayDota, NULL);
                        if (err != QL_OSI_SUCCESS)
                        {
                            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "ql_rtos_timer_create ERROR: %d", err);
                            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
                        }
                    }

                    /* start the timer for delay for DOTA command execution */
                    err = ql_rtos_timer_start(ParserRx_TimerHandler_TimerDelayDota, TIME_MS__DELAY_DOTA, FALSE);
                    if (err != QL_OSI_SUCCESS)
                    {
                        Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "QL FUNCTION - ql_rtos_timer_start - ERROR", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
                    }
                    else
                    {
                        Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "QL FUNCTION - ql_rtos_timer_start - OK"   , __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
                    }
                }
            }

            if (!not_executable)
                command_valid = TRUE;
        }
    }


    /*-----------------------------------------------------------------------------
     * Answer to the command
     *-----------------------------------------------------------------------------*/

    /* copy the report indication */
    *ptr_report = report;

    /* copy the command valid indication */
    *ptr_command_valid = command_valid;

    /* get the current time */
    result = Clock_GetTime(&current_time);

    /* build the current time string */
    if (result)
    {
        /* current time available */
        sprintf(current_time_string,
                "%.3s %02d/%02d/%04d %02d:%02d:%02d",

                /* weekday */
                Clock_WeekDayString(current_time.week_day), // weekday

                /* date */
                current_time.day,                           // day
                current_time.month,                         // month
                current_time.year,                          // year

                /* time */
                current_time.hour,                          // hour
                current_time.minute,                        // minute
                current_time.second);                       // second
    }
    else
    {
        /* current time not available */
        sprintf(current_time_string,

                /* date */
                "???"
                  " "

                "??"
                  "/"
                "??"
                  "/"
                "????"
                  " "

                /* time */
                "??:??:??");
    }

    /* build the answer */
    if      (header_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DOTA, current_time_string, ptr_answer_header              , ptr_command);
    else if (syntax_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DOTA, current_time_string, ANSWER_COMMAND_SYNTAX_ERROR    , ptr_command);
    else if (parameters_error)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DOTA, current_time_string, ANSWER_COMMAND_PARAMETERS_ERROR, ptr_command);
    else if (pwd_required)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DOTA, current_time_string, ANSWER_PASSWORD_REQUIRED       , ptr_command);
    else if (pwd_incorrect)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DOTA, current_time_string, ANSWER_PASSWORD_INCORRECT      , ptr_command);
    else if (not_executable)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DOTA, current_time_string, ANSWER_COMMAND_NOT_EXECUTABLE  , ptr_command);
    else if (not_executed)
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DOTA, current_time_string, ANSWER_COMMAND_NOT_EXECUTED    , ptr_command);
    else
        sprintf(ptr_answer_text[0], " %s - %s - %s - \"%s\"", COMMAND__DOTA, current_time_string, ANSWER_COMMAND_EXECUTED        , ptr_command);

    if (strlen(ptr_answer_text[0]) > 160)
        ptr_answer_text[0][160] = 0x00;

    *ptr_num_answers = 1;

    /* print the answer */
    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ptr_answer_text[0], __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    return TRUE;
}




/*=============================================================================
 * Function   : ParserRx_ParseCommand1Status
 *
 * Description: parse the "STATUS" command
 *
 *              ---------------------------------------------------------------
 *              *** Syntax ***
 *
 *              - Command:  "STATUS"
 *
 *              - Answer :  " STATUS - ..."
 *
 *                            - <aaa>: ...
 *              ---------------------------------------------------------------
 *
 *              ---------------------------------------------------------------
 *              *** Example ***
 *
 *              - Command:  "STATUS
 *
 *              - Answer :  " STATUS - ..."
 *
 *                          TEMP. +15.3C
 *                          CALDAIA ON
 *                          OUT2 OFF
 *                          REGOLA 20.0C 1h57m
 *                          ANTIGELO 5.0C
 *                          IN1 APERTO
 *                          IN2 CHIUSO
 *                          SEGNALE BUONO
 *                          CREDITO 124
 *                          POWER SI
 *
 *                          TIN3 20.1C
 *                          TIN4 17.0C
 *                          OUT1 ON
 *                          OUT2 OFF
 *                          REG1 24C 1:57
 *                          REG2 25C 10:58
 *                          ANT1 8C
 *                          ANT2 8C
 *                          CR1 ON
 *                          CR2 ON
 *                          IN1 APERTO
 *                          IN2 CHIUSO
 *                          C1 ---
 *                          C2 ---
 *                          GSM OTTIMO
 *                          SMS 87
 *                          POWER SI
 *              ---------------------------------------------------------------
 *=============================================================================*/
static bool ParserRx_ParseCommand1Status(bool command_not_to_exe, CLOCK__TIME *ptr_time_tx, ascii *ptr_phone_number, bool is_adm, bool is_crs, bool is_command_ext, ascii *ptr_command, bool header_error, ascii *ptr_answer_header, bool cmd_accepted, bool pwd_present, bool *ptr_report, bool *ptr_command_valid, u8 *ptr_num_answers, ascii **ptr_answer_text, u8 max_size_answer_text)
{
    /* error flags */
           bool   syntax_error;
           bool   parameters_error;

    /* password flags */
           bool   pwd_incorrect;
           bool   pwd_required;

    /* command decoding */
           u8     len_command;
           u8     len_command_decoded;
           u8     len_token;
           ascii *ptr_token;

    /* tokens */
           ascii  token_delimiter;
           bool   tokens_finished;
           u8     id_token;

    /* answer to the commmand */
    static ascii *ptr_answer_strings[2];
    static ascii  answer_strings    [2][160 + 1];

           u8     num_of_answers;
           bool   answer_number;

    /* language strings */
           u16    id_string;
           ascii *ptr_string_cmd;
           ascii *ptr_string_ans;

    /* report flag */
           bool   report;

    /* command valid flag */
           bool   command_valid;

           u8     i;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Command \"STATUS\" received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* set the report flag */
    report           = FALSE;

    /* set the command executed flag */
    command_valid    = FALSE;

    /* clear error flags */
    syntax_error     = FALSE;
    parameters_error = FALSE;

    /* clear password flags */
    pwd_incorrect    = FALSE;
    pwd_required     = FALSE;


    /*-----------------------------------------------------------------------------
     * Password verify
     *-----------------------------------------------------------------------------*/
    if (!cmd_accepted)
    {
        if (pwd_present)
            pwd_incorrect = TRUE;
        else
            pwd_required  = TRUE;
    }


    /*-----------------------------------------------------------------------------
     * Command decoding
     *-----------------------------------------------------------------------------*/

    /* calculate command text length */
    len_command = strlen(ptr_command);

    /* check if last character is a space */
    if (ptr_command[len_command - 1] == ' ')
        syntax_error = TRUE;

    len_command_decoded = 0;

    /* check the header command string */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok2(ptr_command, " ", &token_delimiter);
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Command token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 100);

            /* calculate the token length */
            len_token = (u8)strlen(ptr_token);

            /* update the length of the part of the command decoded */
            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            /* restore the delimiter character removed by 'Utility_Strtok2' function */
            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* extract all the tokens of the command */
    if (!syntax_error)
    {
        ParserRx_NumOfTokens = 0;
        id_token             = 0;
        tokens_finished      = FALSE;

        while (!tokens_finished)
        {
            //snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "id_token: %d", id_token);
            //Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            ptr_token = Utility_Strtok2(NULL, " ", &token_delimiter);
            if (ptr_token != NULL)
            {
                snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token[%d]: \"%s\"", id_token, ptr_token);
                Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

                /* calculate the token length */
                len_token = (u8)strlen(ptr_token);

                /* update the length of the part of the command decoded */
                if ((len_command_decoded + len_token) == len_command)
                    len_command_decoded += (len_token    );
                else
                    len_command_decoded += (len_token + 1);

                /* copy the token */
                strncpy(ParserRx_Tokens[id_token], ptr_token, LEN_MAX_TOKEN);
                ParserRx_Tokens[id_token][LEN_MAX_TOKEN] = 0x00;

                /* restore the delimiter character removed by 'Utility_Strtok2' function */
                if (len_command != len_command_decoded)
                    ptr_token[len_token] = token_delimiter;

                /* conversion to capital letters */
                for (i = 0; i < len_token; i++)
                    ParserRx_Tokens[id_token][i] = toupper((unsigned char)ParserRx_Tokens[id_token][i]);

                /* update the index token */
                id_token++;
                ParserRx_NumOfTokens = id_token;
                if (id_token > NUM_MAX_TOKENS)
                {
                    syntax_error = TRUE;
                    break;
                }
            }
            else
            {
                tokens_finished = TRUE;
            }
        }

        for (id_token = ParserRx_NumOfTokens; id_token < NUM_MAX_TOKENS; id_token++)
        {
            strncpy(ParserRx_Tokens[id_token], "", LEN_MAX_TOKEN);
            ParserRx_Tokens[id_token][LEN_MAX_TOKEN] = 0x00;
        }
    }

    /* check the number of tokens */
    if (!syntax_error)
    {
        if (
             (ParserRx_NumOfTokens != 0)
           )
        {
            syntax_error = TRUE;
        }
    }

    /* check the end of string */
    if (!syntax_error)
    {
        if (len_command != len_command_decoded)
            syntax_error = TRUE;
    }

    /* check the parameters values */
    if (!syntax_error)
    {
        // NOTHING TO DO

        parameters_error = FALSE;
    }


    /*-----------------------------------------------------------------------------
     * Command execution
     *-----------------------------------------------------------------------------*/

    /* command execution (only if command decoding is correct: no syntax error and no parameters error) */
    if ((!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            command_valid = TRUE;
        }
    }


    /*-----------------------------------------------------------------------------
     * Answer to the command
     *-----------------------------------------------------------------------------*/

    /* copy the report indication */
    *ptr_report = report;

    /* copy the command valid indication */
    *ptr_command_valid = command_valid;

    /* build the answer */
    id_string      = STRINGS__COMMAND__STATUS;
    ptr_string_cmd = Strings_GetString(id_string);

    for (i = 0; i < 2; i++)
    {
        answer_strings    [i][0] = 0x00;
        ptr_answer_strings[i]    = &answer_strings[i][0];
    }

    /* build the answer string */
    if ((!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            ParserRx_ParserAnswerStatus(is_command_ext, &num_of_answers, ptr_answer_strings, max_size_answer_text);
        }
    }

    /* build the answer */
    if (syntax_error)
    {
        id_string      = STRINGS__ANSWER__CONFIGURATION_SYNTAX_ERROR;
        ptr_string_ans = Strings_GetString(id_string);
    }
    else if (parameters_error)
    {
        id_string      = STRINGS__ANSWER__COMMAND_PARAMETERS_ERROR;
        ptr_string_ans = Strings_GetString(id_string);
    }
    else if (pwd_required)
    {
        id_string      = STRINGS__ANSWER__PASSWORD_REQUIRED;
        ptr_string_ans = Strings_GetString(id_string);
    }
    else if (pwd_incorrect)
    {
        id_string      = STRINGS__ANSWER__PASSWORD_INCORRECT;
        ptr_string_ans = Strings_GetString(id_string);
    }
    else
    {
        id_string      = STRINGS__EMPTY;
        ptr_string_ans = Strings_GetString(id_string);
    }

    if (strlen(ptr_string_ans) > 0)
    {
        num_of_answers = 1;

        sprintf(answer_strings[0], " %s - %s", ptr_string_cmd, ptr_string_ans);
    }

    if (num_of_answers == 1)
        answer_number = FALSE;
    else
        answer_number = TRUE;

    for (i = 0; i < num_of_answers; i++)
    {

        if (answer_number)
            sprintf(ptr_answer_text[i], " %s (%d/%d) -" NEW_LINE "%s", ptr_string_cmd, i + 1, num_of_answers, answer_strings[i]);
        else
            sprintf(ptr_answer_text[i], "%s"                         ,                                        answer_strings[i]);

        if (strlen(ptr_answer_text[i]) > 160)
            ptr_answer_text[i][160] = 0x00;
    }

    *ptr_num_answers = num_of_answers;

    /* print the answer */
    for (i = 0; i < num_of_answers; i++)
        Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ptr_answer_text[i], __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    return TRUE;
}




/*=============================================================================
 * Function   : ParserRx_ParseCommand1Version
 *
 * Description: parse the "VERSION" command
 *
 *              ---------------------------------------------------------------
 *              *** Syntax ***
 *
 *              - Command:  "VERSION"
 *
 *              - Answer :  " VERSION - MANUFACTURER=<manufacturer> MODEL=<model> VERSION=<version>"
 *
 *                            - <manufacturer>: product manufacturer
 *                            - <model>       : product model
 *                            - <version>     : product FW version
 *              ---------------------------------------------------------------
 *
 *              ---------------------------------------------------------------
 *              *** Example ***
 *
 *              - Command:  "VERSION"
 *
 *              - Answer :  " VERSION - MANUFACTURER="Shitek Technology s.r.l." MODEL="SK0153 - LINKY DIN 4G" VERSION="1.0.2""
 *              ---------------------------------------------------------------
 *
 * Input      : - command_not_to_exe  : indication if the command has to be executed
 *              - ptr_time_tx         : pointer to command transmission time
 *              - ptr_phone_number    : pointer to phone number of the command sender (if it is by SMS)
 *              - is_adm              : indication if the command sender is an administrator
 *              - is_crs              : indication if the command sender is a  Center Service
 *              - is_command_ext      : indication if the command is an extra command
 *              - ptr_command         : pointer to command string to be parsed
 *              - header_error        : header ok status
 *              - ptr_answer_header   : pointer to header answer text
 *              - cmd_accepted        : command accepted indication
 *              - pwd_present         : password present indication
 *              - ptr_report          : pointer where to save the report        indication
 *              - ptr_command_valid   : pointer where to save the command valid indication
 *              - ptr_num_answers     : pointer where to save the number of answers
 *              - ptr_answer_text     : pointer where to save the pointer to the first answer text
 *              - max_size_answer_text: max size of answer text
 * Output     : - FALSE: parser error
 *              - TRUE : parser OK
 *=============================================================================*/
static bool ParserRx_ParseCommand1Version(bool command_not_to_exe, CLOCK__TIME *ptr_time_tx, ascii *ptr_phone_number, bool is_adm, bool is_crs, bool is_command_ext, ascii *ptr_command, bool header_error, ascii *ptr_answer_header, bool cmd_accepted, bool pwd_present, bool *ptr_report, bool *ptr_command_valid, u8 *ptr_num_answers, ascii **ptr_answer_text, u8 max_size_answer_text)
{
    /* error flags */
                bool    syntax_error;
                bool    parameters_error;

    /* password flags */
                bool    pwd_incorrect;
                bool    pwd_required;

    /* command decoding */
                u8      len_command;
                u8      len_command_decoded;
                u8      len_token;
                ascii  *ptr_token;

    /* tokens */
                ascii   token_delimiter;
                bool    tokens_finished;
                u8      id_token;

    /* IDs */
           const ascii *ptr_id_manufacturer;
           const ascii *ptr_id_model;
           const ascii *ptr_id_fw_revision;

    /* answer to the commmand */
    static       ascii  answer_string[160 + 1];

    /* language strings */
                 u16    id_string;
                 ascii *ptr_string_cmd;
                 ascii *ptr_string_ans;
                 ascii *ptr_string_label_1;
                 ascii *ptr_string_label_2;
                 ascii *ptr_string_label_3;

    /* report flag */
                 bool   report;

    /* command valid flag */
                 bool   command_valid;

                 u8     i;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Command \"VERSION\" received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* set the report flag */
    report           = FALSE;

    /* set the command executed flag */
    command_valid    = FALSE;


    /* clear error flags */
    syntax_error     = FALSE;
    parameters_error = FALSE;

    /* clear password flags */
    pwd_incorrect    = FALSE;
    pwd_required     = FALSE;


    /* avoid compiler warning maybe-uninitialized */
    ptr_id_manufacturer = NULL;
    ptr_id_model        = NULL;
    ptr_id_fw_revision  = NULL;


    /*-----------------------------------------------------------------------------
     * Password verify
     *-----------------------------------------------------------------------------*/
    if (!cmd_accepted)
    {
        if (pwd_present)
            pwd_incorrect = TRUE;
        else
            pwd_required  = TRUE;
    }


    /*-----------------------------------------------------------------------------
     * Command decoding
     *-----------------------------------------------------------------------------*/

    /* calculate command text length */
    len_command = strlen(ptr_command);

    /* check if last character is a space */
    if (ptr_command[len_command - 1] == ' ')
        syntax_error = TRUE;

    len_command_decoded = 0;

    /* check the header command string */
    if (!syntax_error)
    {
        ptr_token = Utility_Strtok2(ptr_command, " ", &token_delimiter);
        if (ptr_token != NULL)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Command token: \"%s\"", ptr_token);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 100);

            /* calculate the token length */
            len_token = (u8)strlen(ptr_token);

            /* update the length of the part of the command decoded */
            if ((len_command_decoded + len_token) == len_command)
                len_command_decoded += (len_token    );
            else
                len_command_decoded += (len_token + 1);

            /* restore the delimiter character removed by 'Utility_Strtok2' function */
            if (len_command != len_command_decoded)
                ptr_token[len_token] = ' ';
        }
        else
        {
            syntax_error = TRUE;
        }
    }

    /* extract all the tokens of the command */
    if (!syntax_error)
    {
        ParserRx_NumOfTokens = 0;
        id_token             = 0;
        tokens_finished      = FALSE;

        while (!tokens_finished)
        {
            //snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "id_token: %d", id_token);
            //Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

            ptr_token = Utility_Strtok2(NULL, " ", &token_delimiter);
            if (ptr_token != NULL)
            {
                snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "Token[%d]: \"%s\"", id_token, ptr_token);
                Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

                /* calculate the token length */
                len_token = (u8)strlen(ptr_token);

                /* update the length of the part of the command decoded */
                if ((len_command_decoded + len_token) == len_command)
                    len_command_decoded += (len_token    );
                else
                    len_command_decoded += (len_token + 1);

                /* copy the token */
                strncpy(ParserRx_Tokens[id_token], ptr_token, LEN_MAX_TOKEN);
                ParserRx_Tokens[id_token][LEN_MAX_TOKEN] = 0x00;

                /* restore the delimiter character removed by 'Utility_Strtok2' function */
                if (len_command != len_command_decoded)
                    ptr_token[len_token] = token_delimiter;

                /* conversion to capital letters */
                for (i = 0; i < len_token; i++)
                    ParserRx_Tokens[id_token][i] = toupper((unsigned char)ParserRx_Tokens[id_token][i]);

                /* update the index token */
                id_token++;
                ParserRx_NumOfTokens = id_token;
                if (id_token > NUM_MAX_TOKENS)
                {
                    syntax_error = TRUE;
                    break;
                }
            }
            else
            {
                tokens_finished = TRUE;
            }
        }

        for (id_token = ParserRx_NumOfTokens; id_token < NUM_MAX_TOKENS; id_token++)
        {
            strncpy(ParserRx_Tokens[id_token], "", LEN_MAX_TOKEN);
            ParserRx_Tokens[id_token][LEN_MAX_TOKEN] = 0x00;
        }
    }

    /* check the number of tokens */
    if (!syntax_error)
    {
        if (
             (ParserRx_NumOfTokens != 0)
           )
        {
            syntax_error = TRUE;
        }
    }

    /* check the end of string */
    if (!syntax_error)
    {
        if (len_command != len_command_decoded)
            syntax_error = TRUE;
    }

    /* check the parameters values */
    if (!syntax_error)
    {
        // NOTHING TO DO

        parameters_error = FALSE;
    }


    /*-----------------------------------------------------------------------------
     * Command execution
     *-----------------------------------------------------------------------------*/

    /* command execution (only if command decoding is correct: no syntax error and no parameters error) */
    if ((!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            /* get the identifiers */
            ptr_id_manufacturer  = Id_GetIdManufacturer();
            ptr_id_model         = Id_GetIdModel();
            ptr_id_fw_revision   = Id_GetIdFWRevision();

            command_valid = TRUE;
        }
    }


    /*-----------------------------------------------------------------------------
     * Answer to the command
     *-----------------------------------------------------------------------------*/

    /* copy the report indication */
    *ptr_report = report;

    /* copy the command valid indication */
    *ptr_command_valid = command_valid;

    /* build the answer */
    id_string      = STRINGS__COMMAND__VERSION;
    ptr_string_cmd = Strings_GetString(id_string);

    /* build the answer string */
    if ((!syntax_error) && (!parameters_error))
    {
        /* command decoding is correct: no syntax error and no parameters error */

        if (cmd_accepted)
        {
            id_string          = STRINGS__VERSION__ANS__LABEL__MANUFACTURER;    // "MANUFACTURER"
            ptr_string_label_1 = Strings_GetString(id_string);

            id_string          = STRINGS__VERSION__ANS__LABEL__MODEL;           // "MODEL"
            ptr_string_label_2 = Strings_GetString(id_string);

            id_string          = STRINGS__VERSION__ANS__LABEL__VERSION;         // "VERSION"
            ptr_string_label_3 = Strings_GetString(id_string);

            /* build the answer string */
            sprintf(answer_string,
                                 NEW_LINE
                    "%s \"%s\""  NEW_LINE
                    "%s \"%s\""  NEW_LINE
                    "%s \"%s\"",

                    ptr_string_label_1,
                    ptr_id_manufacturer,

                    ptr_string_label_2,
                    ptr_id_model,

                    ptr_string_label_3,
                    ptr_id_fw_revision);
        }
    }

    /* build the answer */
    if (syntax_error)
    {
        id_string      = STRINGS__ANSWER__CONFIGURATION_SYNTAX_ERROR;
        ptr_string_ans = Strings_GetString(id_string);
    }
    else if (parameters_error)
    {
        id_string      = STRINGS__ANSWER__COMMAND_PARAMETERS_ERROR;
        ptr_string_ans = Strings_GetString(id_string);
    }
    else if (pwd_required)
    {
        id_string      = STRINGS__ANSWER__PASSWORD_REQUIRED;
        ptr_string_ans = Strings_GetString(id_string);
    }
    else if (pwd_incorrect)
    {
        id_string      = STRINGS__ANSWER__PASSWORD_INCORRECT;
        ptr_string_ans = Strings_GetString(id_string);
    }
    else
    {
        ptr_string_ans = answer_string;
    }

    sprintf(ptr_answer_text[0], " %s - %s", ptr_string_cmd, ptr_string_ans);

    if (strlen(ptr_answer_text[0]) > 160)
        ptr_answer_text[0][160] = 0x00;

    *ptr_num_answers = 1;

    /* print the answer */
    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ptr_answer_text[0], __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    return TRUE;
}




