    static ascii                                         string_name_in2                                                                 [NAMES__LEN_MAX_NAME__IN2     + 1];
    static ascii                                         string_name_in3                                                                 [NAMES__LEN_MAX_NAME__IN3     + 1];
    static ascii                                         string_name_in4                                                                 [NAMES__LEN_MAX_NAME__IN4     + 1];
    static ascii                                         string_name_tmin                                                                [NAMES__LEN_MAX_NAME__TMIN    + 1];
    static ascii                                         string_name_tminext                                                             [NAMES__LEN_MAX_NAME__TMINEXT + 1];
    static ascii                                         string_name_tmax                                                                [NAMES__LEN_MAX_NAME__TMAX    + 1];
    static ascii                                         string_name_tmaxext                                                             [NAMES__LEN_MAX_NAME__TMAXEXT + 1];
    static ascii                                         string_name_c1                                                                  [NAMES__LEN_MAX_NAME__C1      + 1];
    static ascii                                         string_name_c2                                                                  [NAMES__LEN_MAX_NAME__C2      + 1];
    static ascii                                         string_tout1                                                                    [20                           + 1];
    static ascii                                         string_tout2                                                                    [20                           + 1];
    static ascii                                         string_tint                                                                     [20                           + 1];
    static ascii                                         string_text                                                                     [20                           + 1];
    static ascii                                         string_power                                                                    [20                           + 1];
    static ascii                                         string_report                                                                   [20                           + 1];
    static ascii                                         string_forward                                                                  [20                           + 1];
    static ascii                                         string_sms_delay                                                                [20                           + 1];
    static ascii                                         string_buttons                                                                  [20                           + 1];

    /* answer to the commmand */
    static ascii                                         string_temp[126 + 1];
    static ascii                                         answer_strings[8][160 + 1];

           u8                                            num_of_answers;
           bool                                          answer_number;

    /* language strings */
           u16                                           id_string;
           ascii                                        *ptr_string_cmd;
           ascii                                        *ptr_string_ans;

           ascii                                        *ptr_string_label_1;
           ascii                                        *ptr_string_label_2;
           ascii                                        *ptr_string_label_3;
           ascii                                        *ptr_string_label_4;
