/*=============================================================================
 * Function   : ParserRx_CommandReset
 *
 * Description: execute the RESET command
 * Input      : - ptr_phone_number: pointer to phone number of the command sender (if it is by SMS)
 * Output     : -
 *=============================================================================*/
static void ParserRx_CommandReset(ascii *ptr_phone_number)
{
    QlOSStatus                  err;

    STARTUP__RESET_RESULT       reset_result;
    STARTUP__RESET_PHONE_NUMBER reset_phone_number;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "RESET command received", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* creation of timer "TimerDelayReset" */
    if (!ParserRx_TimerHandler_TimerDelayReset)
    {
        err = ql_rtos_timer_create(&ParserRx_TimerHandler_TimerDelayReset, Boot_TaskRef_Main, ParserRx_AdlCallback_Timer_TimerDelayReset, NULL);
        if (err != QL_OSI_SUCCESS)
        {
            snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "ql_rtos_timer_create ERROR: %d", err);
            Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
        }
    }

    /* start the timer for delay for RESET command execution */
    err = ql_rtos_timer_start(ParserRx_TimerHandler_TimerDelayReset, TIME_MS__DELAY_RESET, FALSE);
    if (err != QL_OSI_SUCCESS)
    {
        Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "QL FUNCTION - ql_rtos_timer_start - ERROR", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
    }
    else
    {
        Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "QL FUNCTION - ql_rtos_timer_start - OK"   , __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
    }


    /* disable output 1 */
    Outputs_Event_ManualInt_Off();

    /* disable output 2 */
    Outputs_Event_ManualExt_Off();


    /* save the reset result */
    reset_result.reset_result_stored = TRUE;
    Startup_ResetResult_Set(&reset_result);

    /* request the backup to flash objects */
    ProgramFlash_RequestWriteBackup(PROGRAM_FLASH__HANDLE_INDEX__000_RESET, PROGRAM_FLASH__FLASH_ID__000_RESET__RESET_RESULT);


    /* save the reset phone number */
    strncpy(reset_phone_number.reset_phone_number, ptr_phone_number, STARTUP__MAX_LENGTH_RESET_PHONE_NUMBER);
    reset_phone_number.reset_phone_number[STARTUP__MAX_LENGTH_RESET_PHONE_NUMBER] = 0x00;
    Startup_ResetPhoneNumber_Set(&reset_phone_number);

    /* request the backup to flash objects */
    ProgramFlash_RequestWriteBackup(PROGRAM_FLASH__HANDLE_INDEX__000_RESET, PROGRAM_FLASH__FLASH_ID__000_RESET__RESET_PHONE_NUMBER);


  //Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Generate SMS answer event for RESET command", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

    /* generate SMS answer event for RESET command */
  //SmsAnswerEvent_GenerateSmsAnswerEvent(ptr_phone_number, SMS_ANSWER_EVENT__ANSWER_TYPE__RESET);
}




