/*=============================================================================
 * Function   : ParserRx_AdlCallback_Timer_TimerDelayDota
 *
 * Description:
 * Input      : - context:
 * Output     : -
 *=============================================================================*/
static void ParserRx_AdlCallback_Timer_TimerDelayDota(void *context)
{
    DOTA_MAIN__DOTA_PHASE                dota_phase;
    DOTA_MAIN__DOTA_PHASE_1_NUM_ATTEMPTS dota_phase_1_num_attempts;

    BOOT__BOOT_MODE                      boot_mode;

    u8                                   counter;
    bool                                 result;
    ql_errcode_power                     res_power;


    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PHONE, DEBUG_TRACE_TYPE_LOW, "CALLBACK     - TIMER       - DELAY DOTA", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);


    /* set "DOTA phase 1 number of attempts" to zero */
    dota_phase_1_num_attempts = 0;
    DotaMain_DotaPhase1NumAttempts_Set(&dota_phase_1_num_attempts);
    DotaFlash_RequestWriteBackup(DOTA_FLASH__HANDLE_INDEX__000_DOTA     , DOTA_FLASH__FLASH_ID__000_DOTA__PHASE_1_ATTEMPTS);

    /* set "DOTA phase" to DOTA phase 1 */
    dota_phase = DOTA_MAIN__DOTA_PHASE_1;
    DotaMain_DotaPhase_Set(&dota_phase);
    DotaFlash_RequestWriteBackup(DOTA_FLASH__HANDLE_INDEX__000_DOTA     , DOTA_FLASH__FLASH_ID__000_DOTA__PHASE           );

    /* set "boot mode" to DOTA mode */
    boot_mode = BOOT__DOTA_MODE;
    Boot_BootMode_Set(&boot_mode);
    BootFlash_RequestWriteBackup(BOOT_FLASH__HANDLE_INDEX__000_BOOT_MODE, BOOT_FLASH__FLASH_ID__000_BOOT_MODE__BOOT_MODE  );


    /* variable delay before module reset (it is necessary to complete the flash backup) */
    counter = 0;
    while (counter < 20)
    {
        result = ProgramFlash_IsBackupPendent();

        if (!result)
            break;

        ql_rtos_task_sleep_ms(100L);

        counter++;
    }


    //@@@ togliere settaggio AT+WRST
    //@@@ cancellare tutti i +CALA
    //@@@ fermare task
    //@@@ fermare il ReArm del watchdog
    //@@@ disattivare watchdog


    /* reset the module (the module restarts in DOTA mode) */
    Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "Reset the module...", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

    res_power = ql_power_reset(RESET_NORMAL);  //@@@
    if (res_power != QL_POWER_RESET_SUCCESS)
    {
        snprintf(ParserRx_DebugString, sizeof(ParserRx_DebugString), "ql_power_reset ERROR: %d", res_power);
        Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, ParserRx_DebugString, __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);

        while(1);  // cause reset for Application Watchdog
    }
    else
    {
        Debug_SendDebugString1(DEBUG_TRACE_LEVEL_PARSER, DEBUG_TRACE_TYPE_LOW, "ql_power_reset OK", __FILE__, __LINE__, (ascii *)__FUNCTION__, 0);
    }
}




